// =========================================================
// PRODUTO INATIVO?
// =========================================================

function produtoEstaInativo(
    produto
) {

    if (!produto) {
        return false;
    }


    return (
        produto.dados_extra
            ?.inativo === true
    );
}


// =========================================================
// PRODUTO ATIVO?
// =========================================================

function produtoEstaAtivo(
    produto
) {

    return !produtoEstaInativo(
        produto
    );
}


// =========================================================
// ADICIONAR FILTRO DE SITUAÇÃO NA BARRA
// =========================================================

function garantirFiltroSituacaoEstoque() {

    let select =
        document.getElementById(
            'filtroSituacaoEstoque'
        );


    if (select) {
        return select;
    }


    const categoriaSelect =
        document.getElementById(
            'filtroCategoriaEstoque'
        );


    if (!categoriaSelect) {
        return null;
    }


    select =
        document.createElement(
            'select'
        );


    select.id =
        'filtroSituacaoEstoque';


    select.className =
        'form-control';


    select.style.width =
        '145px';


    select.innerHTML = `

        <option value="ativos">
            Ativos
        </option>

        <option value="inativos">
            Inativos
        </option>

        <option value="todos">
            Todos
        </option>

    `;


    select.value =
        estadoFiltrosEstoque
            ?.situacao ||
        'ativos';


    select.addEventListener(
        'change',
        filtrarProdutosEstoque
    );


    categoriaSelect
        .insertAdjacentElement(
            'afterend',
            select
        );


    return select;
}


// =========================================================
// ALTERAR SITUAÇÃO DOS PRODUTOS SELECIONADOS
// =========================================================

async function alterarSituacaoProdutosSelecionados(
    inativar
) {

    const ids =
        Array.from(
            produtosSelecionadosMassa
        );


    if (
        ids.length === 0
    ) {

        showToast(
            '⚠️ Selecione pelo menos um produto.',
            'warning'
        );

        return;
    }


    const produtos =
        produtosEstoque.filter(
            produto =>
                ids.includes(
                    String(
                        produto.id
                    )
                )
        );


    if (
        produtos.length === 0
    ) {

        showToast(
            '❌ Produtos selecionados não encontrados.',
            'error'
        );

        return;
    }


    // =====================================================
    // IGNORAR QUEM JÁ ESTÁ NA SITUAÇÃO DESEJADA
    // =====================================================

    const alterar =
        produtos.filter(
            produto => {

                const inativo =
                    produtoEstaInativo(
                        produto
                    );


                return (
                    inativar
                        ? !inativo
                        : inativo
                );

            }
        );


    if (
        alterar.length === 0
    ) {

        showToast(

            inativar

                ? 'ℹ️ Todos os produtos selecionados já estão inativos.'

                : 'ℹ️ Todos os produtos selecionados já estão ativos.',

            'info'

        );

        return;
    }


    const acao =
        inativar
            ? 'INATIVAR'
            : 'REATIVAR';


    const confirmou =
        confirm(

            `${acao} ${alterar.length} produto(s)?\n\n` +

            (
                inativar

                    ? 'Os produtos deixarão de aparecer na listagem e nos relatórios padrão.'

                    : 'Os produtos voltarão a aparecer normalmente na listagem e nos relatórios.'
            )

        );


    if (!confirmou) {
        return;
    }


    let sucesso =
        0;


    const erros =
        [];


    const agora =
        new Date()
            .toISOString();


    const usuario =
        currentUser?.name ||
        currentUser?.username ||
        'sistema';


    for (
        const produto
        of alterar
    ) {

        try {

            // =================================================
            // PRESERVAR TODO O DADOS_EXTRA
            // =================================================

            const dadosExtra = {

                ...(
                    produto.dados_extra ||
                    {}
                ),

                inativo:
                    !!inativar

            };


            // =================================================
            // AUDITORIA
            // =================================================

            if (
                inativar
            ) {

                dadosExtra.inativado_em =
                    agora;


                dadosExtra.inativado_por =
                    usuario;


                delete dadosExtra
                    .reativado_em;


                delete dadosExtra
                    .reativado_por;

            }

            else {

                dadosExtra.reativado_em =
                    agora;


                dadosExtra.reativado_por =
                    usuario;

            }


            const {
                error
            } =
                await window.supabaseClient
                    .from(
                        'produtos_estoque'
                    )
                    .update({

                        dados_extra:
                            dadosExtra

                    })
                    .eq(
                        'id',
                        produto.id
                    );


            if (
                error
            ) {

                throw error;

            }


            // =================================================
            // MEMÓRIA LOCAL
            // =================================================

            produto.dados_extra =
                dadosExtra;


            sucesso++;


        } catch (
            error
        ) {

            console.error(
                `❌ Erro alterando situação de ${produto.sku}:`,
                error
            );


            erros.push(
                produto.sku ||
                produto.id
            );

        }

    }


    // =====================================================
    // LIMPAR SELEÇÃO
    // =====================================================

    limparSelecaoEstoqueMassa();


    // =====================================================
    // REAPLICAR FILTRO
    //
    // Se estamos em Ativos e inativamos,
    // os produtos desaparecem imediatamente.
    // =====================================================

    aplicarFiltrosEOrdenacao();


    if (
        erros.length === 0
    ) {

        showToast(

            inativar

                ? `✅ ${sucesso} produto(s) inativado(s).`

                : `✅ ${sucesso} produto(s) reativado(s).`,

            'success'

        );

    }

    else {

        showToast(
            `⚠️ ${sucesso} alterado(s) e ${erros.length} erro(s).`,
            'warning'
        );

    }
}


