// =========================================================
// GARANTIR QUE AS SUBCATEGORIAS ESTEJAM CARREGADAS
//
// Evita abrir o cadastro antes do Supabase responder.
// Se duas partes do sistema pedirem ao mesmo tempo,
// reutiliza a mesma Promise em vez de fazer duas consultas.
// =========================================================

async function garantirSubcategoriasEstoqueCarregadas(
    forcarRecarregamento = false
) {

    // Já terminou de carregar nesta sessão
    if (
        !forcarRecarregamento &&
        subcategoriasEstoqueCarregadas
    ) {

        return subcategoriasEstoque;

    }


    // Já existe uma consulta em andamento
    if (
        !forcarRecarregamento &&
        promessaCarregamentoSubcategorias
    ) {

        return await promessaCarregamentoSubcategorias;

    }


    promessaCarregamentoSubcategorias =
        (async () => {

            try {

                console.log(
                    '📂 Garantindo carregamento das subcategorias...'
                );


                const resultado =
                    await carregarSubcategoriasEstoque();


                if (
                    resultado &&
                    typeof resultado === 'object'
                ) {

                    subcategoriasEstoque =
                        resultado;

                }


                subcategoriasEstoqueCarregadas =
                    true;


                console.log(
                    '✅ Subcategorias prontas para uso:',
                    subcategoriasEstoque
                );


                return subcategoriasEstoque;


            } catch (error) {

                console.error(
                    '❌ Erro ao preparar subcategorias:',
                    error
                );


                throw error;


            } finally {

                promessaCarregamentoSubcategorias =
                    null;

            }

        })();


    return await promessaCarregamentoSubcategorias;
}

// =========================================================
// FUNÇÕES PARA VERIFICAÇÃO DE DUPLICIDADE POR 5 PRIMEIROS CARACTERES
// =========================================================

function verificarDuplicidadeSKU(novoSKU, idIgnorar = null) {
    if (!novoSKU) return { duplicado: false };
    
    const prefixo = novoSKU.trim().substring(0, 8).toUpperCase();
    if (prefixo.length < 8) return { duplicado: false };
    
    const existente = produtosEstoque.find(p => {
        if (idIgnorar && p.id == idIgnorar) return false;
        const pSku = (p.sku || '').trim().toUpperCase();
        return pSku.substring(0, 8) === prefixo;
    });
    
    if (existente) {
        return {
            duplicado: true,
            produto: existente,
            mensagem: `Já existe um produto com o prefixo "${prefixo}" (SKU: ${existente.sku} - ${existente.nome})`
        };
    }
    
    return { duplicado: false };
}

// =========================================================
// CARREGAR SUBCATEGORIAS
// =========================================================

async function carregarSubcategoriasEstoque() {

    try {

        console.log(
            '🔄 Carregando subcategorias do estoque...'
        );


        // =================================================
        // SEM SUPABASE
        // =================================================

        if (!window.supabaseClient) {

            const local =
                localStorage.getItem(
                    'subcategorias_estoque'
                );


            subcategoriasEstoque =
                local
                    ? JSON.parse(local)
                    : {};


            console.log(
                '✅ Subcategorias carregadas do localStorage:',
                subcategoriasEstoque
            );


            return subcategoriasEstoque;
        }


        // =================================================
        // SUPABASE
        // =================================================

        const {
            data,
            error
        } =
            await window.supabaseClient
                .from(
                    'configuracoes_sistema'
                )
                .select('*')
                .eq(
                    'chave',
                    'subcategorias_estoque'
                )
                .maybeSingle();


        if (error) {
            throw error;
        }


        if (
            data &&
            data.valor
        ) {

            subcategoriasEstoque =
                typeof data.valor ===
                'string'

                    ? JSON.parse(
                        data.valor
                    )

                    : data.valor;

        } else {

            subcategoriasEstoque = {};

        }


        localStorage.setItem(
            'subcategorias_estoque',
            JSON.stringify(
                subcategoriasEstoque
            )
        );


        console.log(
            '✅ Subcategorias carregadas:',
            subcategoriasEstoque
        );


        return subcategoriasEstoque;


    } catch (error) {

        console.error(
            '❌ Erro carregando subcategorias:',
            error
        );


        try {

            const local =
                localStorage.getItem(
                    'subcategorias_estoque'
                );


            subcategoriasEstoque =
                local
                    ? JSON.parse(local)
                    : {};

        } catch (e) {

            subcategoriasEstoque = {};

        }


        return subcategoriasEstoque;
    }
}


// =========================================================
// SALVAR SUBCATEGORIAS
// =========================================================

async function salvarSubcategoriasEstoque() {

    try {

        localStorage.setItem(
            'subcategorias_estoque',
            JSON.stringify(
                subcategoriasEstoque
            )
        );


        if (
            window.supabaseClient
        ) {

            const {
                error
            } =
                await window.supabaseClient
                    .from(
                        'configuracoes_sistema'
                    )
                    .upsert({

                        chave:
                            'subcategorias_estoque',

                        valor:
                            JSON.stringify(
                                subcategoriasEstoque
                            ),

                        atualizado_em:
                            new Date()
                                .toISOString(),

                        atualizado_por:
                            currentUser?.name ||
                            'sistema'

                    }, {

                        onConflict:
                            'chave'

                    });


            if (error) {
                throw error;
            }

        }


        console.log(
            '✅ Subcategorias salvas:',
            subcategoriasEstoque
        );


        return {
            success: true
        };


    } catch (error) {

        console.error(
            '❌ Erro salvando subcategorias:',
            error
        );


        showToast(
            `Erro ao salvar subcategorias: ${error.message}`,
            'error'
        );


        return {
            success: false,
            error:
                error.message
        };
    }
}


