// =========================================================
// PREPARAR DADOS DO GRÁFICO
//
// AGREGA AS MOVIMENTAÇÕES POR DIA:
//
// vendas
// movimentacaoGeral
// entradas
// saidas
// =========================================================

function prepararDadosGraficoHistorico(movimentos) {

    if (
        !Array.isArray(movimentos) ||
        movimentos.length === 0
    ) {
        return [];
    }


    const mapa =
        new Map();


    // =====================================================
    // FUNÇÃO PARA PEGAR DATA DE SÃO PAULO
    // =====================================================

    function obterPartesData(iso) {

        const formatador =
            new Intl.DateTimeFormat(
                'pt-BR',
                {
                    timeZone:
                        'America/Sao_Paulo',

                    day:
                        '2-digit',

                    month:
                        '2-digit',

                    year:
                        'numeric'
                }
            );


        const partes =
            formatador.formatToParts(
                new Date(iso)
            );


        const valores = {};


        partes.forEach(
            parte => {

                if (
                    parte.type !==
                    'literal'
                ) {

                    valores[
                        parte.type
                    ] =
                        parte.value;

                }

            }
        );


        return {

            dia:
                valores.day,

            mes:
                valores.month,

            ano:
                valores.year

        };
    }


    // =====================================================
    // AGRUPAR
    // =====================================================

    movimentos.forEach(
        mov => {

            const partes =
                obterPartesData(
                    mov.data_hora
                );


            const chave =
                `${partes.ano}-${partes.mes}-${partes.dia}`;


            if (
                !mapa.has(chave)
            ) {

                mapa.set(
                    chave,
                    {
                        chave:
                            chave,

                        data:
                            `${partes.dia}/${partes.mes}/${String(partes.ano).slice(-2)}`,

                        dataCompleta:
                            `${partes.dia}/${partes.mes}/${partes.ano}`,

                        vendas:
                            0,

                        entradas:
                            0,

                        saidas:
                            0,

                        movimentacaoGeral:
                            0
                    }
                );

            }


            const registro =
                mapa.get(chave);


            const quantidade =
                Number(
                    mov.quantidade
                ) || 0;


            // =================================================
            // MOVIMENTAÇÃO GERAL
            //
            // É VOLUME MOVIMENTADO:
            //
            // entrada 5 + saída 3 = 8 movimentadas
            // =================================================

            registro.movimentacaoGeral +=
                quantidade;


            // =================================================
            // ENTRADAS / SAÍDAS
            // =================================================

            if (
                mov.tipo ===
                'entrada'
            ) {

                registro.entradas +=
                    quantidade;

            } else {

                registro.saidas +=
                    quantidade;

            }


            // =================================================
            // VENDAS
            // =================================================

            if (
                mov.tipo_entrada ===
                'venda'
            ) {

                registro.vendas +=
                    quantidade;

            }

        }
    );


    return Array.from(
        mapa.values()
    );
}

// =========================================================
// GRÁFICO DO HISTÓRICO
//
// LINHA 1 = VENDAS
// LINHA 2 = MOVIMENTAÇÃO GERAL
// =========================================================

function renderizarGraficoHistoricoMovimentacoes(
    dados,
    nomeProduto
) {

    const canvas =
        document.getElementById(
            'graficoHistoricoEstoque'
        );


    if (!canvas) {

        console.warn(
            'Canvas do gráfico não encontrado'
        );

        return;
    }


    // =====================================================
    // SEM DADOS
    // =====================================================

    if (
        !dados ||
        dados.length === 0
    ) {

        const container =
            canvas.parentElement;


        if (container) {

            container.innerHTML = `

                <div
                    style="
                        height: 100%;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        color: #6c757d;
                        font-size: 13px;
                    "
                >

                    <div
                        style="
                            text-align: center;
                        "
                    >

                        <i
                            class="fas fa-chart-line"
                            style="
                                display: block;
                                font-size: 24px;
                                margin-bottom: 8px;
                                opacity: 0.5;
                            "
                        ></i>

                        Nenhuma movimentação
                        neste período

                    </div>

                </div>
            `;

        }


        return;
    }


    // =====================================================
    // CARREGAR CHART.JS
    // =====================================================

    if (
        typeof Chart ===
        'undefined'
    ) {

        console.warn(
            'Chart.js não carregado. Carregando...'
        );


        const script =
            document.createElement(
                'script'
            );


        script.src =
            'https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js';


        script.onload =
            function() {

                setTimeout(
                    () =>
                        renderizarGraficoHistoricoMovimentacoes(
                            dados,
                            nomeProduto
                        ),
                    100
                );

            };


        document.head.appendChild(
            script
        );


        return;
    }


    // =====================================================
    // DESTRUIR GRÁFICO ANTERIOR
    // =====================================================

    if (
        window
            ._graficoHistoricoMovimentacoesInstance
    ) {

        window
            ._graficoHistoricoMovimentacoesInstance
            .destroy();


        window
            ._graficoHistoricoMovimentacoesInstance =
            null;

    }


    const ctx =
        canvas.getContext(
            '2d'
        );


    const labels =
        dados.map(
            d => d.data
        );


    const vendas =
        dados.map(
            d => d.vendas
        );


    const movimentacaoGeral =
        dados.map(
            d =>
                d.movimentacaoGeral
        );


    // =====================================================
    // CRIAR GRÁFICO
    // =====================================================

    window
        ._graficoHistoricoMovimentacoesInstance =
        new Chart(
            ctx,
            {

                type:
                    'line',


                data: {

                    labels:
                        labels,


                    datasets: [

                        // =================================
                        // VENDAS
                        // =================================

                        {

                            label:
                                'Vendas',

                            data:
                                vendas,

                            borderColor:
                                '#ffc107',

                            backgroundColor:
                                'rgba(255, 193, 7, 0.10)',

                            borderWidth:
                                3,

                            tension:
                                0.3,

                            fill:
                                false,

                            pointRadius:
                                4,

                            pointHoverRadius:
                                7,

                            pointBackgroundColor:
                                '#ffc107',

                            pointBorderColor:
                                '#ffffff',

                            pointBorderWidth:
                                2

                        },


                        // =================================
                        // MOVIMENTAÇÃO GERAL
                        // =================================

                        {

                            label:
                                'Movimentação geral',

                            data:
                                movimentacaoGeral,

                            borderColor:
                                '#00ADEE',

                            backgroundColor:
                                'rgba(0, 173, 238, 0.10)',

                            borderWidth:
                                3,

                            tension:
                                0.3,

                            fill:
                                false,

                            pointRadius:
                                4,

                            pointHoverRadius:
                                7,

                            pointBackgroundColor:
                                '#00ADEE',

                            pointBorderColor:
                                '#ffffff',

                            pointBorderWidth:
                                2

                        }

                    ]

                },


                options: {

                    responsive:
                        true,

                    maintainAspectRatio:
                        false,


                    interaction: {

                        intersect:
                            false,

                        mode:
                            'index'

                    },


                    plugins: {

                        // =============================
                        // LEGENDA
                        // =============================

                        legend: {

                            display:
                                true,

                            position:
                                'top',

                            labels: {

                                font: {

                                    size:
                                        11,

                                    weight:
                                        '600'

                                },

                                color:
                                    '#495057',

                                usePointStyle:
                                    true,

                                pointStyle:
                                    'circle'

                            }

                        },


                        // =============================
                        // TOOLTIP
                        // =============================

                        tooltip: {

                            callbacks: {

                                title:
                                    function(context) {

                                        if (
                                            !context ||
                                            context.length === 0
                                        ) {
                                            return '';
                                        }


                                        const index =
                                            context[0]
                                                .dataIndex;


                                        const dado =
                                            dados[index];


                                        return dado
                                            ?.dataCompleta ||
                                            '';

                                    },


                                label:
                                    function(context) {

                                        const index =
                                            context.dataIndex;


                                        const dado =
                                            dados[index];


                                        if (!dado) {
                                            return '';
                                        }


                                        // =====================
                                        // VENDAS
                                        // =====================

                                        if (
                                            context.datasetIndex ===
                                            0
                                        ) {

                                            return `Vendas: ${dado.vendas} unidade(s)`;

                                        }


                                        // =====================
                                        // MOVIMENTAÇÃO GERAL
                                        // =====================

                                        return [

                                            `Movimentação geral: ${dado.movimentacaoGeral} unidade(s)`,

                                            `Entradas: +${dado.entradas}`,

                                            `Saídas: -${dado.saidas}`

                                        ];

                                    }

                            }

                        }

                    },


                    scales: {

                        // =============================
                        // EIXO X
                        // =============================

                        x: {

                            grid: {
                                display:
                                    false
                            },


                            ticks: {

                                font: {
                                    size:
                                        9
                                },

                                maxTicksLimit:
                                    20,

                                color:
                                    '#6c757d'

                            }

                        },


                        // =============================
                        // EIXO Y
                        // =============================

                        y: {

                            beginAtZero:
                                true,


                            grid: {

                                color:
                                    'rgba(0,0,0,0.05)',

                                drawBorder:
                                    false

                            },


                            ticks: {

                                precision:
                                    0,

                                font: {
                                    size:
                                        10
                                },

                                color:
                                    '#6c757d'

                            },


                            title: {

                                display:
                                    true,

                                text:
                                    'Unidades',

                                color:
                                    '#6c757d',

                                font: {
                                    size:
                                        11
                                }

                            }

                        }

                    }

                }

            }
        );


    console.log(
        `✅ Gráfico de vendas/movimentações renderizado para ${nomeProduto}`
    );
}

// =========================================================
// FUNÇÃO PARA RENDERIZAR O GRÁFICO
// =========================================================

function renderizarGraficoHistorico(dados, nomeProduto) {
    const canvas = document.getElementById('graficoHistoricoEstoque');
    if (!canvas) {
        console.warn('Canvas do gráfico não encontrado');
        return;
    }
    
    if (typeof Chart === 'undefined') {
        console.warn('Chart.js não carregado. Tentando carregar...');
        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js';
        script.onload = function() {
            console.log('Chart.js carregado, renderizando gráfico...');
            setTimeout(() => renderizarGraficoHistorico(dados, nomeProduto), 200);
        };
        document.head.appendChild(script);
        return;
    }
    
    if (window._graficoHistoricoInstance) {
        window._graficoHistoricoInstance.destroy();
        window._graficoHistoricoInstance = null;
    }
    
    const ctx = canvas.getContext('2d');
    
    const labels = dados.map(d => d.data);
    const saldos = dados.map(d => d.saldo);
    
    const pointColors = dados.map(d => {
        if (d.tipo === 'entrada') return '#28a745';
        return '#dc3545';
    });
    
    const gradient = ctx.createLinearGradient(0, 0, 0, 200);
    gradient.addColorStop(0, 'rgba(0, 173, 238, 0.3)');
    gradient.addColorStop(1, 'rgba(0, 173, 238, 0.05)');
    
    window._graficoHistoricoInstance = new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [{
                label: 'Saldo em Estoque',
                data: saldos,
                borderColor: '#00ADEE',
                backgroundColor: gradient,
                fill: true,
                tension: 0.3,
                pointBackgroundColor: pointColors,
                pointBorderColor: '#ffffff',
                pointBorderWidth: 2,
                pointRadius: 5,
                pointHoverRadius: 8,
                borderWidth: 3
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    display: true,
                    position: 'top',
                    labels: {
                        font: { size: 11, weight: '600' },
                        color: '#495057',
                        usePointStyle: true,
                        pointStyle: 'circle'
                    }
                },
                tooltip: {
                    callbacks: {
                        label: function(context) {
                            const index = context.dataIndex;
                            const dado = dados[index];
                            if (!dado) return '';
                            return [
                                `Saldo: ${dado.saldo} unidades`,
                                `${dado.tipo === 'entrada' ? '➕ Entrada' : '➖ Saída'}: ${dado.quantidade} unidades`
                            ];
                        }
                    }
                }
            },
            scales: {
                x: {
                    grid: { display: false },
                    ticks: {
                        font: { size: 9 },
                        maxTicksLimit: 15,
                        color: '#6c757d'
                    }
                },
                y: {
                    grid: {
                        color: 'rgba(0,0,0,0.05)',
                        drawBorder: false
                    },
                    ticks: {
                        font: { size: 10 },
                        color: '#6c757d',
                        stepSize: Math.max(1, Math.ceil(Math.max(...saldos) / 8))
                    },
                    title: {
                        display: true,
                        text: 'Quantidade',
                        color: '#6c757d',
                        font: { size: 11 }
                    }
                }
            },
            interaction: {
                intersect: false,
                mode: 'index'
            }
        }
    });
    
    console.log('✅ Gráfico do histórico renderizado com sucesso!');
}

// =========================================================
// REGISTRAR VENDAS DE NF-e NO HISTÓRICO (SEM BAIXAR ESTOQUE)
// VERSÃO ATUALIZADA - COMPARAÇÃO POR 8 CARACTERES
// =========================================================

window.registrarVendasNFesEmitidas = async function() {
    console.log('📦 Registrando vendas de NF-e no histórico (sem baixar estoque)...');
    
    try {
        if (!window.supabaseClient) {
            showToast('⚠️ Supabase não disponível', 'warning');
            return { totalVendas: 0, totalErros: 1, error: 'Supabase não disponível' };
        }
        
        showToast('🔄 Registrando vendas no histórico...', 'info');
        
        // Buscar NF-e emitidas
        const { data: nfes, error } = await window.supabaseClient
            .from('nfe_emitidas')
            .select('*')
            .order('data_emissao', { ascending: false })
            .limit(200);
        
        if (error) {
            console.error('❌ Erro ao buscar NF-e:', error);
            showToast('❌ Erro ao buscar NF-e: ' + error.message, 'error');
            return { totalVendas: 0, totalErros: 1, error: error.message };
        }
        
        if (!nfes || nfes.length === 0) {
            console.log('✅ Nenhuma NF-e encontrada.');
            showToast('✅ Nenhuma NF-e para processar.', 'info');
            return { totalVendas: 0, totalErros: 0 };
        }
        
        console.log(`📦 Processando ${nfes.length} NF-e...`);
        
        let totalVendas = 0;
        let totalErros = 0;
        let detalhes = [];
        let nfesProcessadas = 0;
        let todosSkusEncontrados = [];
        let todosSkusNaoEncontrados = [];
        
        // ===== FUNÇÃO PARA EXTRAIR OS 8 CARACTERES PRINCIPAIS DO SKU =====
        function extrairSkuBase(sku) {
            if (!sku) return '';
            
            let skuLimpo = sku.trim();
            
            // Remove o prefixo de 3 dígitos (quantidade) se existir
            if (/^\d{3}/.test(skuLimpo)) {
                skuLimpo = skuLimpo.replace(/^\d{3}/, '');
            }
            
            // Retorna apenas os 8 primeiros caracteres
            return skuLimpo.substring(0, 8).toUpperCase();
        }
        
        // =========================================================
// FUNÇÃO EXTRAIR SKUS DO CÓDIGO - VERSÃO CORRIGIDA
// =========================================================
function extrairSkusDoCodigo(codigo) {
    if (!codigo) return [];
    
    console.log(`🔍 Processando código: "${codigo}"`);
    
    if (codigo.includes('.')) {
        const partes = codigo.split('.');
        console.log(`📦 ${partes.length} partes encontradas (separadas por ponto)`);
        
        const skusExtraidos = [];
        for (const parte of partes) {
            let skuReal = parte;
            let quantidadePrefixo = 1;
            
            // 🔥 REMOVE 3 DÍGITOS DO SKU DO ANÚNCIO
            const match = parte.match(/^(\d{3})(.+)$/);
            if (match) {
                quantidadePrefixo = parseInt(match[1]) || 1;
                skuReal = match[2];
                console.log(`  🔹 Parte com prefixo: "${parte}" → Prefixo: ${quantidadePrefixo}, SKU Real: "${skuReal}"`);
            } else {
                console.log(`  🔹 Parte sem prefixo: "${parte}"`);
                skuReal = parte;
            }
            
            // 🔥 USA extrairSkuBaseSistema (NÃO REMOVE NADA) - porque já removemos o prefixo
            const skuBase = extrairSkuBaseSistema(skuReal);
            console.log(`  🔹 Base: "${skuBase}"`);
            
            skusExtraidos.push({
                sku: skuReal,
                skuBase: skuBase,
                quantidadePorKit: quantidadePrefixo || 1
            });
        }
        return skusExtraidos;
    } else {
        let skuReal = codigo;
        let quantidadePrefixo = 1;
        
        // 🔥 REMOVE 3 DÍGITOS DO SKU DO ANÚNCIO
        const match = codigo.match(/^(\d{3})(.+)$/);
        if (match) {
            quantidadePrefixo = parseInt(match[1]) || 1;
            skuReal = match[2];
            console.log(`  🔹 SKU com prefixo: "${codigo}" → Prefixo: ${quantidadePrefixo}, SKU Real: "${skuReal}"`);
        } else {
            console.log(`  🔹 SKU sem prefixo: "${codigo}"`);
            skuReal = codigo;
        }
        
        // 🔥 USA extrairSkuBaseSistema (NÃO REMOVE NADA) - porque já removemos o prefixo
        const skuBase = extrairSkuBaseSistema(skuReal);
        console.log(`  🔹 Base: "${skuBase}"`);
        
        return [{
            sku: skuReal,
            skuBase: skuBase,
            quantidadePorKit: quantidadePrefixo || 1
        }];
    }
}
        
        // ===== BUSCAR PRODUTO POR BASE DE 8 CARACTERES =====
        async function buscarProdutoPorBase(skuBase) {
            if (!skuBase) return null;
            
            // Busca todos os produtos (cache local)
            if (typeof produtosEstoque !== 'undefined' && Array.isArray(produtosEstoque) && produtosEstoque.length > 0) {
                const encontrado = produtosEstoque.find(p => {
                    const baseSistema = extrairSkuBase(p.sku);
                    return baseSistema === skuBase;
                });
                if (encontrado) return encontrado;
            }
            
            // Fallback: busca no Supabase
            try {
                const { data: produtos, error: prodsError } = await window.supabaseClient
                    .from('produtos_estoque')
                    .select('id, quantidade, nome, sku');
                
                if (prodsError) return null;
                
                const encontrado = produtos.find(p => {
                    const baseSistema = extrairSkuBase(p.sku);
                    return baseSistema === skuBase;
                });
                return encontrado || null;
            } catch (e) {
                console.warn('⚠️ Erro ao buscar produtos no Supabase:', e);
                return null;
            }
        }
        
        for (const nfe of nfes) {
            try {
                const chave = nfe.chave_acesso || nfe.id || 'SEM_CHAVE';
                console.log(`\n📄 Processando NF-e: ${chave.substring(0, 20)}...`);
                
                let skusParaProcessar = [];
                
                // ===== EXTRAIR DO XML =====
                if (nfe.xml_assinado) {
                    try {
                        const parser = new DOMParser();
                        const xmlDoc = parser.parseFromString(nfe.xml_assinado, 'application/xml');
                        const dets = xmlDoc.querySelectorAll('det');
                        
                        console.log(`🔍 Encontrados ${dets.length} produtos no XML`);
                        
                        dets.forEach(det => {
                            const prod = det.querySelector('prod');
                            if (prod) {
                                const cProd = prod.querySelector('cProd')?.textContent || '';
                                const xProd = prod.querySelector('xProd')?.textContent || '';
                                const qCom = parseFloat(prod.querySelector('qCom')?.textContent || '0');
                                
                                let codigoOriginal = cProd;
                                
                                const infAdProd = prod.querySelector('infAdProd')?.textContent || '';
                                if (infAdProd) {
                                    const skuMatch = infAdProd.match(/SKU[:\s]*([A-Za-z0-9\-_.]+)/i);
                                    if (skuMatch) {
                                        codigoOriginal = skuMatch[1];
                                        console.log(`🔍 SKU encontrado em infAdProd: ${codigoOriginal}`);
                                    }
                                }
                                
                                console.log(`📦 Produto: Código="${codigoOriginal}", Nome="${xProd}", Quantidade=${qCom}`);
                                
                                const skusExtraidos = extrairSkusDoCodigo(codigoOriginal);
                                
                                for (const skuInfo of skusExtraidos) {
                                    if (skuInfo.sku && skuInfo.sku !== 'SEM_SKU' && skuInfo.sku !== 'N/A' && skuInfo.sku !== '') {
                                        skusParaProcessar.push({
                                            sku: skuInfo.sku,
                                            skuBase: skuInfo.skuBase,
                                            quantidade: qCom * skuInfo.quantidadePorKit,
                                            nome: xProd || 'Produto',
                                            codigoOriginal: codigoOriginal
                                        });
                                    }
                                }
                            }
                        });
                        
                        console.log(`📦 ${skusParaProcessar.length} SKUs extraídos para processar`);
                        
                    } catch (e) {
                        console.warn('⚠️ Erro ao extrair produtos do XML:', e);
                    }
                }
                
                // ===== SE NÃO TEM SKUS, CONTINUA =====
                if (skusParaProcessar.length === 0) {
                    console.warn(`⚠️ Nenhum SKU encontrado na NF-e ${chave.substring(0, 15)}`);
                    detalhes.push(`NF-e ${chave.substring(0, 15)}: Nenhum SKU encontrado`);
                    totalErros++;
                    continue;
                }
                
                // ===== REGISTRAR CADA SKU NO HISTÓRICO (SEM BAIXAR ESTOQUE) =====
                let itensRegistrados = 0;
                let erros = [];
                
                for (const item of skusParaProcessar) {
                    console.log(`🔍 Buscando SKU: "${item.sku}" (base: "${item.skuBase}") no estoque...`);
                    
                    if (!item.sku || item.sku === 'SEM_SKU' || item.sku === 'N/A' || item.sku === '') {
                        erros.push(`SKU vazio para ${item.nome}`);
                        continue;
                    }
                    
                    // ===== 1ª TENTATIVA: BUSCAR PELA BASE DE 8 CARACTERES =====
                    let produto = null;
                    
                    if (item.skuBase) {
                        produto = await buscarProdutoPorBase(item.skuBase);
                        if (produto) {
                            console.log(`✅ Produto encontrado pela BASE de 8 caracteres: "${item.skuBase}" → ${produto.sku}`);
                        }
                    }
                    
                    // ===== 2ª TENTATIVA: BUSCAR DIRETAMENTE PELO SKU COMPLETO =====
                    if (!produto) {
                        const skuLimpo = item.sku.trim();
                        const formasBusca = [
                            skuLimpo,
                            skuLimpo.replace(/^0+/, ''),
                            skuLimpo.padStart(6, '0'),
                            skuLimpo.toLowerCase(),
                            skuLimpo.toUpperCase()
                        ];
                        
                        for (const skuBusca of [...new Set(formasBusca)]) {
                            if (!skuBusca || skuBusca === '') continue;
                            
                            const { data: prod, error: prodError } = await window.supabaseClient
                                .from('produtos_estoque')
                                .select('id, quantidade, nome, sku')
                                .eq('sku', skuBusca)
                                .maybeSingle();
                            
                            if (!prodError && prod) {
                                produto = prod;
                                console.log(`✅ Produto encontrado com SKU "${skuBusca}": ${prod.sku}`);
                                break;
                            }
                        }
                    }
                    
                    // ===== 3ª TENTATIVA: BUSCA PARCIAL (ILIKE) =====
                    if (!produto && item.skuBase) {
                        const { data: prods, error: prodsError } = await window.supabaseClient
                            .from('produtos_estoque')
                            .select('id, quantidade, nome, sku')
                            .ilike('sku', `%${item.skuBase}%`)
                            .limit(5);
                        
                        if (!prodsError && prods && prods.length > 0) {
                            // Verifica qual tem a base correspondente
                            const encontrado = prods.find(p => {
                                const baseSistema = extrairSkuBase(p.sku);
                                return baseSistema === item.skuBase;
                            });
                            if (encontrado) {
                                produto = encontrado;
                                console.log(`✅ Produto encontrado por ILIKE com base correspondente: ${produto.sku}`);
                            } else {
                                produto = prods[0];
                                console.log(`⚠️ Produto encontrado por ILIKE (possível incompatibilidade): ${produto.sku}`);
                            }
                        }
                    }
                    
                    if (produto) {
                        const quantidadeVenda = Math.ceil(item.quantidade || 1);
                        itensRegistrados++;
                        todosSkusEncontrados.push(produto.sku);
                        
                        // ===== REGISTRAR NO HISTÓRICO SEM BAIXAR ESTOQUE =====
                        try {
                            const { error: movError } = await window.supabaseClient
                                .from('estoque_movimentacoes')
                                .insert([{
                                    produto_id: produto.id,
                                    tipo: 'saida',
                                    quantidade: quantidadeVenda,
                                    usuario: 'Sistema (NF-e antiga)',
                                    numero_documento: `NFE-${chave.substring(0, 10)}`,
                                    tipo_entrada: 'venda',
                                    data_hora: nfe.data_emissao || new Date().toISOString(),
                                }]);
                            
                            if (movError) {
                                erros.push(`Erro ao registrar venda de ${produto.sku}: ${movError.message}`);
                                console.warn(`⚠️ Erro ao registrar venda de ${produto.sku}:`, movError);
                            } else {
                                console.log(`✅ Venda registrada no histórico: ${produto.sku} (${produto.nome}) - ${quantidadeVenda} un (sem baixar estoque)`);
                            }
                        } catch (movErr) {
                            erros.push(`Erro ao registrar venda de ${produto.sku}: ${movErr.message}`);
                            console.warn(`⚠️ Erro ao registrar venda:`, movErr);
                        }
                    } else {
                        const msg = `SKU "${item.sku}" (base: "${item.skuBase}") não encontrado no estoque (original: ${item.codigoOriginal})`;
                        erros.push(msg);
                        todosSkusNaoEncontrados.push(item.sku);
                        console.warn(`❌ ${msg}`);
                    }
                }
                
                if (itensRegistrados > 0) {
                    nfesProcessadas++;
                    totalVendas += itensRegistrados;
                    
                    // Marcar como processada
                    try {
                        await window.supabaseClient
                            .from('nfe_emitidas')
                            .update({ 
                                processada: true,
                                processada_em: new Date().toISOString(),
                                registrada_historico: true
                            })
                            .eq('id', nfe.id);
                    } catch (e) {
                        console.warn('⚠️ Não foi possível marcar NF-e como processada:', e);
                    }
                }
                
                if (erros.length > 0) {
                    totalErros += erros.length;
                    detalhes.push(`NF-e ${chave.substring(0, 15)}: ${erros.join('; ')}`);
                }
                
            } catch (err) {
                console.error(`❌ Erro ao processar NF-e ${nfe.id}:`, err);
                totalErros++;
                detalhes.push(`NF-e ${nfe.id}: ${err.message}`);
            }
        }
        
        // ===== RESUMO FINAL =====
        console.log('\n📊 ===== RESUMO FINAL =====');
        console.log(`✅ Vendas registradas no histórico: ${totalVendas}`);
        console.log(`❌ Erros: ${totalErros}`);
        console.log(`📄 NF-e processadas: ${nfesProcessadas}`);
        if (todosSkusEncontrados.length > 0) {
            console.log(`🔍 SKUs encontrados: ${todosSkusEncontrados.length}`);
        }
        if (todosSkusNaoEncontrados.length > 0) {
            console.log(`❓ SKUs NÃO encontrados (${todosSkusNaoEncontrados.length}): ${todosSkusNaoEncontrados.join(', ')}`);
        }
        
        let mensagem = `✅ ${totalVendas} venda(s) registradas no histórico de estoque!`;
        if (totalErros > 0) {
            mensagem += ` ⚠️ ${totalErros} erro(s) encontrados.`;
        }
        if (nfesProcessadas === 0 && totalVendas === 0) {
            mensagem = 'ℹ️ Nenhuma NF-e pendente para registrar.';
        }
        showToast(mensagem, totalErros > 0 ? 'warning' : 'success');
        
        return { totalVendas, totalErros, detalhes, nfesProcessadas, todosSkusEncontrados, todosSkusNaoEncontrados };
        
    } catch (error) {
        console.error('❌ Erro ao registrar vendas de NF-e:', error);
        showToast('❌ Erro ao registrar vendas: ' + error.message, 'error');
        return { totalVendas: 0, totalErros: 1, error: error.message };
    }
};

console.log('✅ Função registrarVendasNFesEmitidas registrada (versão com comparação por 8 caracteres)');

// =========================================================
// REVERTER ESTOQUE DAS NF-e (VERSÃO ATUALIZADA)
// COMPARAÇÃO POR 8 CARACTERES
// =========================================================

window.reverterEstoqueNFes = async function() {
    console.log('🔄 Iniciando reversão de estoque das NF-e (compara por 8 caracteres)...');
    
    try {
        if (!window.supabaseClient) {
            showToast('⚠️ Supabase não disponível', 'warning');
            return;
        }
        
        if (!confirm('⚠️ Isso vai REVERTER o estoque das NF-e que foram baixadas incorretamente.\n\nA comparação será feita pelos 8 primeiros caracteres do SKU.\n\nDeseja continuar?')) {
            return;
        }
        
        showToast('🔄 Revertendo estoque...', 'info');
        
        // Buscar TODAS as NF-e
        const { data: nfes, error } = await window.supabaseClient
            .from('nfe_emitidas')
            .select('*')
            .order('data_emissao', { ascending: false })
            .limit(200);
        
        if (error) {
            console.error('❌ Erro ao buscar NF-e:', error);
            showToast('❌ Erro ao buscar NF-e: ' + error.message, 'error');
            return;
        }
        
        if (!nfes || nfes.length === 0) {
            console.log('✅ Nenhuma NF-e encontrada.');
            showToast('✅ Nenhuma NF-e para reverter.', 'info');
            return;
        }
        
        console.log(`📦 Processando ${nfes.length} NF-e...`);
        
        let totalRevertido = 0;
        let totalErros = 0;
        let nfesRevertidas = 0;
        let detalhes = [];
        let produtosRevertidosList = [];
        
        // ===== FUNÇÃO PARA EXTRAIR OS 8 CARACTERES PRINCIPAIS DO SKU =====
        function extrairSkuBase(sku) {
            if (!sku) return '';
            
            let skuLimpo = sku.trim();
            
            // Remove o prefixo de 3 dígitos (quantidade) se existir
            if (/^\d{3}/.test(skuLimpo)) {
                skuLimpo = skuLimpo.replace(/^\d{3}/, '');
            }
            
            // Retorna apenas os 8 primeiros caracteres
            return skuLimpo.substring(0, 8).toUpperCase();
        }
        
        function extrairSkusDoCodigo(codigo) {
    if (!codigo) return [];
    
    console.log(`🔍 Processando código: "${codigo}"`);
    
    // Remove prefixo de 3 dígitos se existir
    let skuReal = codigo;
    let quantidadePrefixo = 1;
    
    const match = codigo.match(/^(\d{3})(.+)$/);
    if (match) {
        quantidadePrefixo = parseInt(match[1]) || 1;
        skuReal = match[2];
        console.log(`  🔹 Prefixo: ${quantidadePrefixo}, SKU Real: "${skuReal}"`);
    } else {
        console.log(`  🔹 Sem prefixo: "${codigo}"`);
        skuReal = codigo;
    }
    
    const skuBase = extrairSkuBase(skuReal);
    return [{
        sku: skuReal,
        skuBase: skuBase,
        quantidadePorKit: quantidadePrefixo || 1
    }];
}
        
        // =========================================================
// FUNÇÃO BUSCAR PRODUTO POR BASE - VERSÃO CORRIGIDA
// =========================================================
async function buscarProdutoPorBase(skuBase) {
    if (!skuBase) return null;
    
    console.log(`🔍 Buscando produto com base: "${skuBase}"`);
    
    // Busca no cache local
    if (typeof produtosEstoque !== 'undefined' && Array.isArray(produtosEstoque) && produtosEstoque.length > 0) {
        const encontrado = produtosEstoque.find(p => {
            // 🔥 USA extrairSkuBaseSistema (NÃO REMOVE NADA)
            const baseSistema = extrairSkuBaseSistema(p.sku);
            return baseSistema === skuBase;
        });
        if (encontrado) {
            console.log(`✅ Produto encontrado no cache: ${encontrado.sku}`);
            return encontrado;
        }
    }
    
    // Fallback: busca no Supabase
    try {
        if (!window.supabaseClient) return null;
        
        const { data: produtos, error: prodsError } = await window.supabaseClient
            .from('produtos_estoque')
            .select('id, quantidade, nome, sku, dados_extra, preco, categoria');
        
        if (prodsError) {
            console.warn('⚠️ Erro ao buscar produtos no Supabase:', prodsError);
            return null;
        }
        
        const encontrado = produtos.find(p => {
            const baseSistema = extrairSkuBaseSistema(p.sku);
            return baseSistema === skuBase;
        });
        
        if (encontrado) {
            console.log(`✅ Produto encontrado no Supabase: ${encontrado.sku}`);
            return encontrado;
        }
        
        console.log(`❌ Produto não encontrado para base: "${skuBase}"`);
        return null;
    } catch (e) {
        console.warn('⚠️ Erro ao buscar produtos no Supabase:', e);
        return null;
    }
}
        
        for (const nfe of nfes) {
            try {
                const chave = nfe.chave_acesso || nfe.id || 'SEM_CHAVE';
                console.log(`\n📄 Processando NF-e: ${chave.substring(0, 20)}...`);
                
                let skusParaReverter = [];
                
                // ===== EXTRAIR DO XML =====
                if (nfe.xml_assinado) {
                    try {
                        const parser = new DOMParser();
                        const xmlDoc = parser.parseFromString(nfe.xml_assinado, 'application/xml');
                        const dets = xmlDoc.querySelectorAll('det');
                        
                        dets.forEach(det => {
                            const prod = det.querySelector('prod');
                            if (prod) {
                                const cProd = prod.querySelector('cProd')?.textContent || '';
                                const qCom = parseFloat(prod.querySelector('qCom')?.textContent || '0');
                                
                                let codigoOriginal = cProd;
                                
                                const infAdProd = prod.querySelector('infAdProd')?.textContent || '';
                                if (infAdProd) {
                                    const skuMatch = infAdProd.match(/SKU[:\s]*([A-Za-z0-9\-_.]+)/i);
                                    if (skuMatch) {
                                        codigoOriginal = skuMatch[1];
                                    }
                                }
                                
                                const skusExtraidos = extrairSkusDoCodigo(codigoOriginal);
                                
                                for (const skuInfo of skusExtraidos) {
                                    if (skuInfo.sku && skuInfo.sku !== 'SEM_SKU' && skuInfo.sku !== 'N/A' && skuInfo.sku !== '') {
                                        skusParaReverter.push({
                                            sku: skuInfo.sku,
                                            skuBase: skuInfo.skuBase,
                                            quantidade: qCom * skuInfo.quantidadePorKit
                                        });
                                    }
                                }
                            }
                        });
                        
                        console.log(`📦 ${skusParaReverter.length} SKUs extraídos para reverter`);
                        
                    } catch (e) {
                        console.warn('⚠️ Erro ao extrair produtos do XML:', e);
                    }
                }
                
                // Se não tem SKUs no XML, tentar extrair do campo produtos
                if (skusParaReverter.length === 0 && nfe.produtos) {
                    try {
                        let produtosData = nfe.produtos;
                        if (typeof produtosData === 'string') {
                            produtosData = JSON.parse(produtosData);
                        }
                        if (Array.isArray(produtosData) && produtosData.length > 0) {
                            for (const p of produtosData) {
                                const sku = p.sku || p.cProd || 'SEM_SKU';
                                const qtd = p.quantidade || p.qCom || 1;
                                const skusExtraidos = extrairSkusDoCodigo(sku);
                                for (const skuInfo of skusExtraidos) {
                                    if (skuInfo.sku && skuInfo.sku !== 'SEM_SKU') {
                                        skusParaReverter.push({
                                            sku: skuInfo.sku,
                                            skuBase: skuInfo.skuBase,
                                            quantidade: qtd * skuInfo.quantidadePorKit
                                        });
                                    }
                                }
                            }
                            console.log(`📦 ${skusParaReverter.length} SKUs extraídos do campo produtos`);
                        }
                    } catch (e) {
                        console.warn('⚠️ Erro ao extrair do campo produtos:', e);
                    }
                }
                
                if (skusParaReverter.length === 0) {
                    console.warn(`⚠️ Nenhum SKU encontrado na NF-e ${chave.substring(0, 15)}`);
                    continue;
                }
                
                // ===== REVERTER CADA SKU =====
                let itensRevertidos = 0;
                let erros = [];
                let produtosRevertidos = [];
                
                for (const item of skusParaReverter) {
                    if (!item.sku || item.sku === 'SEM_SKU' || item.sku === 'N/A') continue;
                    
                    console.log(`🔍 Buscando SKU: "${item.sku}" (base: "${item.skuBase}") para reverter...`);
                    
                    // ===== 1ª TENTATIVA: BUSCAR PELA BASE DE 8 CARACTERES =====
                    let produto = null;
                    
                    if (item.skuBase) {
                        produto = await buscarProdutoPorBase(item.skuBase);
                        if (produto) {
                            console.log(`✅ Produto encontrado pela BASE de 8 caracteres: "${item.skuBase}" → ${produto.sku}`);
                        }
                    }
                    
                    // ===== 2ª TENTATIVA: BUSCAR DIRETAMENTE PELO SKU COMPLETO =====
                    if (!produto) {
                        const skuLimpo = item.sku.trim();
                        const formasBusca = [
                            skuLimpo,
                            skuLimpo.replace(/^0+/, ''),
                            skuLimpo.padStart(6, '0'),
                            skuLimpo.toLowerCase(),
                            skuLimpo.toUpperCase()
                        ];
                        
                        for (const skuBusca of [...new Set(formasBusca)]) {
                            if (!skuBusca || skuBusca === '') continue;
                            
                            const { data: prod, error: prodError } = await window.supabaseClient
                                .from('produtos_estoque')
                                .select('id, quantidade, nome, sku')
                                .eq('sku', skuBusca)
                                .maybeSingle();
                            
                            if (!prodError && prod) {
                                produto = prod;
                                console.log(`✅ Produto encontrado com SKU "${skuBusca}": ${prod.sku}`);
                                break;
                            }
                        }
                    }
                    
                    // ===== 3ª TENTATIVA: BUSCA PARCIAL (ILIKE) =====
                    if (!produto && item.skuBase) {
                        const { data: prods, error: prodsError } = await window.supabaseClient
                            .from('produtos_estoque')
                            .select('id, quantidade, nome, sku')
                            .ilike('sku', `%${item.skuBase}%`)
                            .limit(5);
                        
                        if (!prodsError && prods && prods.length > 0) {
                            const encontrado = prods.find(p => {
                                const baseSistema = extrairSkuBase(p.sku);
                                return baseSistema === item.skuBase;
                            });
                            if (encontrado) {
                                produto = encontrado;
                                console.log(`✅ Produto encontrado por ILIKE com base correspondente: ${produto.sku}`);
                            } else {
                                produto = prods[0];
                                console.log(`⚠️ Produto encontrado por ILIKE (possível incompatibilidade): ${produto.sku}`);
                            }
                        }
                    }
                    
                    if (produto) {
                        // ===== ADICIONAR DE VOLTA AO ESTOQUE =====
                        const quantidadeReverter = Math.ceil(item.quantidade || 1);
                        const novaQuantidade = (produto.quantidade || 0) + quantidadeReverter;
                        
                        const { error: updateError } = await window.supabaseClient
                            .from('produtos_estoque')
                            .update({ 
                                quantidade: novaQuantidade,
                                updated_at: new Date().toISOString()
                            })
                            .eq('id', produto.id);
                        
                        if (updateError) {
                            erros.push(`Erro ao reverter ${produto.sku}: ${updateError.message}`);
                            console.error(`❌ Erro ao reverter ${produto.sku}:`, updateError);
                        } else {
                            itensRevertidos++;
                            produtosRevertidos.push({
                                sku: produto.sku,
                                quantidade: quantidadeReverter,
                                novaQuantidade: novaQuantidade
                            });
                            produtosRevertidosList.push({
                                sku: produto.sku,
                                quantidade: quantidadeReverter,
                                nfe: chave.substring(0, 10)
                            });
                            console.log(`✅ Estoque revertido: ${produto.sku} +${quantidadeReverter} (agora: ${novaQuantidade})`);
                        }
                    } else {
                        erros.push(`SKU "${item.sku}" (base: "${item.skuBase}") não encontrado`);
                        console.warn(`❌ SKU não encontrado: "${item.sku}" (base: "${item.skuBase}")`);
                    }
                }
                
                if (itensRevertidos > 0) {
                    totalRevertido += itensRevertidos;
                    nfesRevertidas++;
                    
                    // Registrar no histórico a reversão
                    for (const prod of produtosRevertidos) {
                        try {
                            const { data: prodData } = await window.supabaseClient
                                .from('produtos_estoque')
                                .select('id')
                                .eq('sku', prod.sku)
                                .single();
                            
                            if (prodData) {
                                await window.supabaseClient
                                    .from('estoque_movimentacoes')
                                    .insert([{
                                        produto_id: prodData.id,
                                        tipo: 'entrada',
                                        quantidade: prod.quantidade,
                                        usuario: 'Sistema (Reversão NF-e)',
                                        numero_documento: `REV-${chave.substring(0, 10)}`,
                                        tipo_entrada: 'reversao',
                                        data_hora: new Date().toISOString()
                                    }]);
                            }
                        } catch (e) {
                            console.warn('⚠️ Erro ao registrar movimentação de reversão:', e);
                        }
                    }
                }
                
                if (erros.length > 0) {
                    totalErros += erros.length;
                    detalhes.push(`NF-e ${chave.substring(0, 15)}: ${erros.join('; ')}`);
                }
                
            } catch (err) {
                console.error(`❌ Erro ao reverter NF-e ${nfe.id}:`, err);
                totalErros++;
                detalhes.push(`NF-e ${nfe.id}: ${err.message}`);
            }
        }
        
        // Atualizar estoque local
        if (totalRevertido > 0 && typeof window.carregarProdutosEstoque === 'function') {
            await window.carregarProdutosEstoque();
        }
        
        console.log('\n📊 ===== REVERSÃO CONCLUÍDA =====');
        console.log(`✅ NF-e revertidas: ${nfesRevertidas}`);
        console.log(`✅ Itens revertidos: ${totalRevertido}`);
        console.log(`❌ Erros: ${totalErros}`);
        
        if (produtosRevertidosList.length > 0) {
            console.log('📦 Produtos revertidos:');
            produtosRevertidosList.forEach(p => {
                console.log(`  - ${p.sku}: +${p.quantidade} (NF: ${p.nfe})`);
            });
        }
        
        let mensagem = `✅ ${totalRevertido} item(ns) revertidos em ${nfesRevertidas} NF-e!`;
        if (totalErros > 0) {
            mensagem += ` ⚠️ ${totalErros} erro(s) encontrados.`;
        }
        if (totalRevertido === 0) {
            mensagem = 'ℹ️ Nenhum item foi revertido. Verifique se as NF-e já foram processadas.';
        }
        showToast(mensagem, totalErros > 0 ? 'warning' : 'success');
        
        return { totalRevertido, totalErros, nfesRevertidas, detalhes, produtosRevertidos: produtosRevertidosList };
        
    } catch (error) {
        console.error('❌ Erro ao reverter estoque:', error);
        showToast('❌ Erro ao reverter estoque: ' + error.message, 'error');
        return { totalRevertido: 0, totalErros: 1, error: error.message };
    }
};

console.log('✅ Função reverterEstoqueNFes registrada (versão com comparação por 8 caracteres)');

// =========================================================
// REGISTRAR VENDA NO ESTOQUE (CHAMADO PELA EMISSÃO DE NF-E)
// =========================================================

async function registrarVendaEstoque(produtoId, quantidade, numeroVenda, usuario) {
    try {
        if (!window.supabaseClient) {
            console.warn('Supabase não disponível para registrar venda');
            return { success: false, error: 'Supabase não disponível' };
        }
        
        // Buscar produto atual
        const { data: produto, error: errProd } = await window.supabaseClient
            .from('produtos_estoque')
            .select('quantidade, sku, nome')
            .eq('id', produtoId)
            .single();
        
        if (errProd) throw errProd;
        
        if (!produto) {
            return { success: false, error: 'Produto não encontrado' };
        }
        
        // Verificar se há estoque suficiente
        if ((produto.quantidade || 0) < quantidade) {
            return { 
                success: false, 
                error: `Estoque insuficiente! Disponível: ${produto.quantidade}, Vendido: ${quantidade}` 
            };
        }
        
        const novaQuantidade = (produto.quantidade || 0) - quantidade;
        
        // Atualizar estoque
        const { error: errUpdate } = await window.supabaseClient
            .from('produtos_estoque')
            .update({ quantidade: novaQuantidade })
            .eq('id', produtoId);
        
        if (errUpdate) throw errUpdate;
        
        // Registrar movimentação como VENDA
        const numeroMov = await gerarNumeroMovimentacao();
        const { error: errMov } = await window.supabaseClient
            .from('estoque_movimentacoes')
            .insert([{
                produto_id: produtoId,
                tipo: 'saida',
                quantidade: quantidade,
                usuario: usuario || currentUser?.name || 'sistema',
                numero_movimentacao: numeroMov,
                numero_documento: `NFE-${numeroVenda}`,
                tipo_entrada: 'venda',
                data_hora: new Date().toISOString(),
                saldo_apos: novaQuantidade
            }]);
        
        if (errMov) throw errMov;
        
        // Atualizar o produto localmente
        const produtoLocal = produtosEstoque.find(p => p.id == produtoId);
        if (produtoLocal) {
            produtoLocal.quantidade = novaQuantidade;
        }
        
        console.log(`✅ Venda registrada: ${quantidade} unidade(s) de ${produto.sku} (${produto.nome})`);
        return { 
            success: true, 
            novaQuantidade: novaQuantidade,
            produto: produto.sku
        };
        
    } catch (error) {
        console.error('❌ Erro ao registrar venda:', error);
        return { success: false, error: error.message };
    }
}

// Expor função global
window.registrarVendaEstoque = registrarVendaEstoque;

// =========================================================
// FUNÇÃO PARA RENDERIZAR O GRÁFICO DO HISTÓRICO
// =========================================================

function renderizarGraficoHistorico(dados, nomeProduto) {
    const canvas = document.getElementById('graficoHistoricoEstoque');
    if (!canvas) {
        console.warn('Canvas do gráfico não encontrado');
        return;
    }
    
    // Verificar se o Chart.js está disponível
    if (typeof Chart === 'undefined') {
        console.warn('Chart.js não carregado. Tentando carregar...');
        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js';
        script.onload = function() {
            console.log('Chart.js carregado, renderizando gráfico...');
            setTimeout(() => renderizarGraficoHistorico(dados, nomeProduto), 200);
        };
        document.head.appendChild(script);
        return;
    }
    
    // Destruir gráfico existente se houver
    if (window._graficoHistoricoInstance) {
        window._graficoHistoricoInstance.destroy();
        window._graficoHistoricoInstance = null;
    }
    
    const ctx = canvas.getContext('2d');
    
    // Preparar dados para o gráfico
    const labels = dados.map(d => d.data);
    const saldos = dados.map(d => d.saldo);
    
    // Cores baseadas no tipo de movimentação
    const pointColors = dados.map(d => {
        if (d.tipo === 'entrada') return '#28a745';
        return '#dc3545';
    });
    
    // Criar dataset com gradiente
    const gradient = ctx.createLinearGradient(0, 0, 0, 200);
    gradient.addColorStop(0, 'rgba(0, 173, 238, 0.3)');
    gradient.addColorStop(1, 'rgba(0, 173, 238, 0.05)');
    
    window._graficoHistoricoInstance = new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [{
                label: 'Saldo em Estoque',
                data: saldos,
                borderColor: '#00ADEE',
                backgroundColor: gradient,
                fill: true,
                tension: 0.3,
                pointBackgroundColor: pointColors,
                pointBorderColor: '#ffffff',
                pointBorderWidth: 2,
                pointRadius: 5,
                pointHoverRadius: 8,
                borderWidth: 3
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    display: true,
                    position: 'top',
                    labels: {
                        font: {
                            size: 11,
                            weight: '600'
                        },
                        color: '#495057',
                        usePointStyle: true,
                        pointStyle: 'circle'
                    }
                },
                tooltip: {
                    callbacks: {
                        label: function(context) {
                            const index = context.dataIndex;
                            const dado = dados[index];
                            return [
                                `Saldo: ${dado.saldo} unidades`,
                                `${dado.tipo === 'entrada' ? '➕ Entrada' : '➖ Saída'}: ${dado.quantidade} unidades`
                            ];
                        }
                    }
                }
            },
            scales: {
                x: {
                    grid: {
                        display: false
                    },
                    ticks: {
                        font: {
                            size: 9
                        },
                        maxTicksLimit: 15,
                        color: '#6c757d'
                    }
                },
                y: {
                    grid: {
                        color: 'rgba(0,0,0,0.05)',
                        drawBorder: false
                    },
                    ticks: {
                        font: {
                            size: 10
                        },
                        color: '#6c757d',
                        stepSize: Math.max(1, Math.ceil(Math.max(...saldos) / 8))
                    },
                    title: {
                        display: true,
                        text: 'Quantidade',
                        color: '#6c757d',
                        font: {
                            size: 11
                        }
                    }
                }
            },
            interaction: {
                intersect: false,
                mode: 'index'
            }
        }
    });
    
    console.log('✅ Gráfico do histórico renderizado com sucesso!');
}

// =========================================================
// GERAR NÚMERO DE MOVIMENTAÇÃO
// =========================================================

async function gerarNumeroMovimentacao() {
    const hoje = new Date();
    const ano = hoje.getFullYear();
    const mes = String(hoje.getMonth() + 1).padStart(2, '0');
    const dia = String(hoje.getDate()).padStart(2, '0');
    const prefixo = `${ano}${mes}${dia}`;
    const { data, error } = await window.supabaseClient
        .from('estoque_movimentacoes')
        .select('numero_movimentacao')
        .ilike('numero_movimentacao', `MOV-${prefixo}-%`)
        .order('numero_movimentacao', { ascending: false })
        .limit(1);
    let sequencial = 1;
    if (data && data.length > 0) {
        const ultimo = data[0].numero_movimentacao;
        const match = ultimo.match(/\d{4}$/);
        if (match) sequencial = parseInt(match[0]) + 1;
    }
    return `MOV-${prefixo}-${String(sequencial).padStart(4, '0')}`;
}

// =========================================================
// FUNÇÕES DE SALVAR PRODUTO COM VERIFICAÇÃO DE DUPLICIDADE
// PRESERVA:
// - Categorias padrão
// - Categorias customizadas
// - Subcategorias
// - Estoque "a caminho"
// =========================================================

async function salvarProdutoEstoque() {

    const id =
        document.getElementById('produtoId').value;

    const nome =
        document.getElementById('produtoNome').value.trim();

    const preco =
        parseFloat(
            document.getElementById('produtoPreco').value
        ) || 0;

    const descricao =
        document.getElementById('produtoDescricao').value.trim();

    const categoria =
        document.getElementById('produtoCategoria').value;

    const toggleSync =
        document.getElementById('bloquearSyncML');


    // =====================================================
    // USUÁRIO / PERMISSÕES
    // =====================================================

    const username =
        currentUser?.username?.toLowerCase() || '';

    const isAdmin =
        usuariosAdmin.includes(username);

    const podeModificarSync =
        usuariosAutorizadosSync.includes(username) ||
        isAdmin;


    // =====================================================
    // PRODUTO EXISTENTE
    //
    // Usado SOMENTE para preservar informações já salvas
    // que não fazem parte dos campos dinâmicos.
    // =====================================================

    const produtoExistenteAtual =
        id
            ? produtosEstoque.find(
                p => p.id == id
            )
            : null;


    const dadosExtraAnteriores =
        produtoExistenteAtual?.dados_extra || {};


    // =====================================================
    // SINCRONIZAÇÃO ML
    // =====================================================

    let bloquearSync = false;


    if (
        podeModificarSync &&
        toggleSync
    ) {

        bloquearSync =
            toggleSync.checked;

    }

    else if (id) {

        const produtoExistente =
            produtosEstoque.find(
                p => p.id == id
            );


        if (produtoExistente) {

            bloquearSync =
                produtoExistente.bloquear_sync_ml ||
                produtoExistente.dados_extra?.bloquear_sync_ml ||
                false;

        }

    }


    // =====================================================
    // CAMPOS OBRIGATÓRIOS
    // =====================================================

    if (
        !nome ||
        !categoria
    ) {

        if (
            window.showToast
        ) {

            showToast(
                'Nome e Categoria são obrigatórios',
                'warning'
            );

        }


        return;
    }


    // =====================================================
    // SKU
    // =====================================================

    const sku =
        document.getElementById(
            'produtoSKU'
        ).value.trim();


    if (!sku) {

        showToast(
            'SKU é obrigatório',
            'warning'
        );

        return;
    }


    // =====================================================
    // VERIFICAR DUPLICIDADE
    // =====================================================

    const duplicidade =
        verificarDuplicidadeSKU(
            sku,
            id || null
        );


    if (
        duplicidade.duplicado
    ) {

        showToast(
            `❌ ${duplicidade.mensagem}`,
            'error'
        );


        const campoSku =
            document.getElementById(
                'produtoSKU'
            );


        campoSku.focus();


        campoSku.style.borderColor =
            '#dc3545';


        setTimeout(
            () => {

                campoSku.style.borderColor =
                    '';

            },
            3000
        );

        return;
    }

    // =====================================================
    // COLETAR DADOS EXTRA
    // =====================================================

    const dadosExtra = {};

    if (
        (categoria === 'Raios' || categoria === 'Parafusos')
        &&
        produtoExistenteAtual
    ) {

        if (
            dadosExtraAnteriores.quantidade_a_caminho !==
            undefined
        ) {

            dadosExtra.quantidade_a_caminho =
                dadosExtraAnteriores.quantidade_a_caminho;

        }

        if (
            dadosExtraAnteriores.quantidade_a_caminho_atualizado_em
        ) {

            dadosExtra.quantidade_a_caminho_atualizado_em =
                dadosExtraAnteriores
                    .quantidade_a_caminho_atualizado_em;

        }


        if (
            dadosExtraAnteriores.quantidade_a_caminho_atualizado_por
        ) {

            dadosExtra.quantidade_a_caminho_atualizado_por =
                dadosExtraAnteriores
                    .quantidade_a_caminho_atualizado_por;

        }

    }


    // =====================================================
    // CAMPOS DA CATEGORIA / SUBCATEGORIA
    //
    // NÃO ALTERADO:
    //
    // Continua usando sua getCamposPorCategoria atual.
    // Portanto:
    //
    // Raios normal → campos de Raios
    // Raios/Nipples → campos de Nipples
    // Categorias customizadas → continuam funcionando
    // =====================================================

    const campos =
        getCamposPorCategoria(
            categoria
        );


    for (
        const campo
        of campos
    ) {

        const el =
            document.getElementById(
                `campo_${campo.nome}`
            );


        if (el) {

            // =============================================
            // CHECKBOX
            // =============================================

            if (
                campo.tipo ===
                'checkbox'
            ) {

                dadosExtra[
                    campo.nome
                ] =
                    el.checked;

            }


            // =============================================
            // MLB CODES
            // =============================================

            else if (
                campo.nome ===
                    'mlb_codes' &&
                el.value.trim()
            ) {

                const mlbText =
                    el.value.trim();


                if (
                    !validarMLBCodes(
                        mlbText
                    )
                ) {

                    showToast(
                        `Formato inválido para MLB Codes. Use: "MLB1496273494, MLB4220545731"`,
                        'error'
                    );


                    el.focus();


                    return;
                }


                const valores =
                    mlbText
                        .split(',')
                        .map(
                            v =>
                                v.trim()
                        )
                        .filter(
                            v => v
                        );


                dadosExtra[
                    campo.nome
                ] =
                    valores;

            }


            // =============================================
            // OUTROS CAMPOS
            // =============================================

            else {

                let valor =
                    el.value;


                if (
                    campo.tipo ===
                        'number' &&
                    valor !== ''
                ) {

                    valor =
                        parseFloat(
                            valor
                        );

                }


                if (
                    campo.validacao ===
                        'numero_virgula' &&
                    valor !== ''
                ) {

                    if (
                        !/^[0-9]+(,[0-9]+)?$/.test(
                            valor
                        )
                    ) {

                        showToast(
                            `O campo "${campo.label}" deve conter apenas números e vírgula`,
                            'warning'
                        );


                        el.focus();


                        return;
                    }

                }


                dadosExtra[
                    campo.nome
                ] =
                    valor;

            }

        }

    }


    // =====================================================
    // SINCRONIZAÇÃO ML
    // =====================================================

    if (
        podeModificarSync
    ) {

        dadosExtra.bloquear_sync_ml =
            bloquearSync;

    }

    else {

        delete dadosExtra
            .bloquear_sync_ml;

    }


    // =====================================================
    // ÂNGULOS PARA ROLAMENTOS
    // =====================================================

    if (
        categoria ===
        'Rolamentos'
    ) {

        const anguloInt =
            document.getElementById(
                'campo_angulo_interno'
            );


        const anguloExt =
            document.getElementById(
                'campo_angulo_externo'
            );


        const angulosDiv =
            document.getElementById(
                'camposAngulosRolamento'
            );


        if (
            angulosDiv &&
            angulosDiv.style.display !==
                'none'
        ) {

            if (
                anguloInt &&
                anguloInt.value.trim() !==
                    ''
            ) {

                const val =
                    anguloInt.value.trim();


                if (
                    !/^[0-9]+(,[0-9]+)?$/.test(
                        val
                    )
                ) {

                    showToast(
                        'Ângulo interno deve conter apenas números e vírgula',
                        'warning'
                    );


                    anguloInt.focus();


                    return;
                }


                dadosExtra.angulo_interno =
                    val;

            }


            if (
                anguloExt &&
                anguloExt.value.trim() !==
                    ''
            ) {

                const val =
                    anguloExt.value.trim();


                if (
                    !/^[0-9]+(,[0-9]+)?$/.test(
                        val
                    )
                ) {

                    showToast(
                        'Ângulo externo deve conter apenas números e vírgula',
                        'warning'
                    );


                    anguloExt.focus();


                    return;
                }


                dadosExtra.angulo_externo =
                    val;

            }

        }

    }


    // =====================================================
    // SKUs DO KIT
    // =====================================================

    let skusKit = [];


    const tbody =
        document.getElementById(
            'kitSkusBody'
        );


    if (tbody) {

        const rows =
            tbody.querySelectorAll(
                'tr'
            );


        rows.forEach(
            row => {

                const isMuted =
                    row.querySelector(
                        '.text-muted'
                    );


                if (
                    isMuted
                ) {
                    return;
                }


                const skuFilhoInput =
                    row.querySelector(
                        '.kit-sku-filho'
                    );


                const quantidadeInput =
                    row.querySelector(
                        '.kit-quantidade'
                    );


                if (
                    skuFilhoInput &&
                    quantidadeInput
                ) {

                    const skuFilho =
                        skuFilhoInput
                            .value
                            .trim();


                    const quantidade =
                        parseInt(
                            quantidadeInput.value
                        ) || 1;


                    if (
                        skuFilho
                    ) {

                        skusKit.push({

                            sku_filho:
                                skuFilho,

                            quantidade:
                                quantidade

                        });

                    }

                }

            }
        );

    }


    // =====================================================
    // SUBCATEGORIA ATUAL
    //
    // ÚNICA PEQUENA CORREÇÃO NO BULK:
    //
    // Raios → bulk permitido
    // Raios → Nipples → bulk NÃO permitido
    // =====================================================

    const subcategoriaAtual =
        document.getElementById(
            'campo_subcategoria'
        )?.value || '';


    // =====================================================
    // BULK MODE PARA RAIOS
    // =====================================================

    const bulkPanel =
        document.getElementById(
            'bulkModePanel'
        );


    const isBulkMode =
        (
            categoria ===
                'Raios' &&

            !subcategoriaAtual &&

            !id &&

            bulkPanel &&

            bulkPanel.style.display ===
                'block'
        );


    if (
        isBulkMode
    ) {

        const rows =
            document.querySelectorAll(
                '#bulkTamanhosBody tr'
            );


        const bulkItems =
            [];


        const tamanhosSet =
            new Set();


        const skusSet =
            new Set();


        for (
            let row
            of rows
        ) {

            const tamanho =
                row.querySelector(
                    '.bulk-tamanho'
                )?.value?.trim();


            const skuItem =
                row.querySelector(
                    '.bulk-sku'
                )?.value?.trim();


            const quantidade =
                parseInt(
                    row.querySelector(
                        '.bulk-quantidade'
                    )?.value
                ) || 0;


            if (
                !tamanho ||
                !skuItem
            ) {

                showToast(
                    'Todos os tamanhos e SKUs devem ser preenchidos',
                    'warning'
                );


                return;
            }


            // =============================================
            // VERIFICAR DUPLICIDADE
            // =============================================

            const dupBulk =
                verificarDuplicidadeSKU(
                    skuItem
                );


            if (
                dupBulk.duplicado
            ) {

                showToast(
                    `❌ SKU "${skuItem}" duplicado - ${dupBulk.mensagem}`,
                    'error'
                );


                return;
            }


            if (
                tamanhosSet.has(
                    tamanho
                )
            ) {

                showToast(
                    `Tamanho ${tamanho} duplicado`,
                    'warning'
                );


                return;
            }


            if (
                skusSet.has(
                    skuItem
                )
            ) {

                showToast(
                    `SKU ${skuItem} duplicado`,
                    'warning'
                );


                return;
            }


            tamanhosSet.add(
                tamanho
            );


            skusSet.add(
                skuItem
            );


            bulkItems.push({

                tamanho,

                quantidade,

                sku:
                    skuItem

            });

        }


        if (
            bulkItems.length ===
            0
        ) {

            showToast(
                'Adicione pelo menos um tamanho',
                'warning'
            );


            return;
        }


        if (
            !confirm(
                `Criar ${bulkItems.length} produto(s) com as mesmas informações de marca/modelo/cabeça?`
            )
        ) {

            return;
        }


        let created =
            0;


        let errors =
            [];


        // =================================================
        // PEGAR MLB CODES
        // =================================================

        const mlbField =
            document.getElementById(
                'campo_mlb_codes'
            );


        let mlbCodes =
            [];


        if (
            mlbField &&
            mlbField.value.trim()
        ) {

            const mlbText =
                mlbField.value.trim();


            if (
                !validarMLBCodes(
                    mlbText
                )
            ) {

                showToast(
                    `Formato inválido para MLB Codes. Use: "MLB1496273494, MLB4220545731"`,
                    'error'
                );


                mlbField.focus();


                return;
            }


            mlbCodes =
                mlbText
                    .split(',')
                    .map(
                        v =>
                            v.trim()
                    )
                    .filter(
                        v => v
                    );

        }


        // =================================================
        // CRIAR RAIOS
        // =================================================

        for (
            const item
            of bulkItems
        ) {

            // =============================================
            // VERIFICAR SE JÁ EXISTE
            // =============================================

            const {
                data: existing
            } =
                await window
                    .supabaseClient
                    .from(
                        'produtos_estoque'
                    )
                    .select(
                        'id'
                    )
                    .eq(
                        'sku',
                        item.sku
                    )
                    .maybeSingle();


            if (
                existing
            ) {

                errors.push(
                    `${item.sku} (já existe)`
                );


                continue;
            }


            // =============================================
            // CÓPIA DOS DADOS EXTRA
            // =============================================

            const produtoDadosExtra = {

                ...dadosExtra

            };


            produtoDadosExtra.tamanhoraio =
                item.tamanho;


            // =============================================
            // MLB
            // =============================================

            if (
                mlbCodes.length >
                0
            ) {

                produtoDadosExtra.mlb_codes =
                    mlbCodes;

            }


            // =============================================
            // SYNC
            // =============================================

            if (
                podeModificarSync
            ) {

                produtoDadosExtra.bloquear_sync_ml =
                    bloquearSync;

            }


            // =============================================
            // PRODUTO
            // =============================================

            const produtoData = {

                nome:
                    nome,

                sku:
                    item.sku,

                quantidade:
                    item.quantidade,

                preco:
                    preco,

                descricao:
                    descricao,

                categoria:
                    categoria,

                dados_extra:
                    produtoDadosExtra,

                ultimo_custo:
                    0,

                custo_medio:
                    0,

                historico_custos:
                    [],

                bloquear_sync_ml:
                    podeModificarSync
                        ? bloquearSync
                        : false

            };


            try {

                const {
                    data,
                    error
                } =
                    await window
                        .supabaseClient
                        .from(
                            'produtos_estoque'
                        )
                        .insert([
                            produtoData
                        ])
                        .select();


                if (
                    error
                ) {
                    throw error;
                }


                created++;


                if (
                    item.quantidade >
                    0
                ) {

                    await registrarMovimentacao(

                        data[0].id,

                        'entrada',

                        item.quantidade,

                        'Criação em massa - Raios',

                        'nova'

                    );

                }

            }

            catch (
                err
            ) {

                errors.push(
                    `${item.sku}: ${err.message}`
                );

            }

        }


        // =================================================
        // RESULTADO DO BULK
        // =================================================

        let msg =
            `✅ ${created} produto(s) criado(s)!`;


        if (
            errors.length
        ) {

            msg +=
                ` ⚠️ Erros: ${errors.join(', ')}`;

        }


        showToast(
            msg,
            errors.length > 0
                ? 'warning'
                : 'success'
        );


        fecharModalProdutoEstoque();


        await carregarProdutosEstoque();


        return;
    }


    // =====================================================
    // MODO NORMAL
    // =====================================================

    const quantidade =
        parseInt(
            document.getElementById(
                'produtoQuantidade'
            ).value
        ) || 0;


    let ultimoCusto =
        0;


    let custoMedio =
        0;


    let historicoCustos =
        [];


    let bloquearSyncExistente =
        false;


    if (id) {

        const produtoExistente =
            produtosEstoque.find(
                p =>
                    p.id == id
            );


        if (
            produtoExistente
        ) {

            ultimoCusto =
                produtoExistente.ultimo_custo ||
                produtoExistente.dados_extra?.ultimo_custo ||
                0;


            custoMedio =
                produtoExistente.custo_medio ||
                produtoExistente.dados_extra?.custo_medio ||
                0;


            historicoCustos =
                produtoExistente.historico_custos ||
                [];


            bloquearSyncExistente =
                produtoExistente.bloquear_sync_ml ||
                produtoExistente.dados_extra?.bloquear_sync_ml ||
                false;

        }

    }


    // =====================================================
    // DADOS DO PRODUTO
    // =====================================================

    const produtoData = {

        nome,

        sku,

        quantidade,

        preco,

        descricao,

        categoria,

        dados_extra:
            dadosExtra,

        ultimo_custo:
            ultimoCusto,

        custo_medio:
            custoMedio,

        historico_custos:
            historicoCustos,

        bloquear_sync_ml:
            podeModificarSync
                ? bloquearSync
                : bloquearSyncExistente

    };


    // =====================================================
    // SALVAR
    // =====================================================

    try {

        let produtoSalvo;


        const idValido =
            id &&
            id !==
                'undefined' &&
            id !==
                'null' &&
            id.trim() !==
                '';


        // =================================================
        // ATUALIZAR
        // =================================================

        if (
            idValido
        ) {

            const {
                data,
                error
            } =
                await window
                    .supabaseClient
                    .from(
                        'produtos_estoque'
                    )
                    .update(
                        produtoData
                    )
                    .eq(
                        'id',
                        parseInt(id)
                    )
                    .select();


            if (
                error
            ) {
                throw error;
            }


            produtoSalvo =
                data &&
                data[0]
                    ? data[0]
                    : null;


            if (
                produtoSalvo
            ) {

                showToast(
                    'Produto atualizado!',
                    'success'
                );

            }

            else {

                showToast(
                    'Erro: produto não encontrado para edição.',
                    'error'
                );


                return;
            }

        }


        // =================================================
        // CRIAR
        // =================================================

        else {

            const {
                data,
                error
            } =
                await window
                    .supabaseClient
                    .from(
                        'produtos_estoque'
                    )
                    .insert([
                        produtoData
                    ])
                    .select();


            if (
                error
            ) {
                throw error;
            }


            produtoSalvo =
                data &&
                data[0]
                    ? data[0]
                    : null;


            if (
                produtoSalvo
            ) {

                if (
                    quantidade >
                    0
                ) {

                    await registrarMovimentacao(

                        produtoSalvo.id,

                        'entrada',

                        quantidade,

                        'Criação do produto',

                        'nova'

                    );

                }


                showToast(
                    'Produto adicionado!',
                    'success'
                );

            }

            else {

                showToast(
                    'Erro ao criar produto.',
                    'error'
                );


                return;
            }

        }


        // =================================================
        // KIT
        // =================================================

        if (
            sku &&
            skusKit.length >
            0
        ) {

            const result =
                await salvarSkusKit(
                    sku,
                    skusKit
                );


            if (
                !result.success
            ) {

                console.error(
                    'Erro ao salvar SKUs do kit:',
                    result.error
                );


                showToast(
                    'Erro ao salvar composição do kit: ' +
                    result.error,
                    'warning'
                );

            }

        }

        else if (
            sku
        ) {

            await excluirSkusKit(
                sku
            );

        }


        // =================================================
        // FECHAR MODAL
        // =================================================

        if (
            !entradaEmProcessamento
        ) {

            fecharModalProdutoEstoque();

        }


        // =================================================
        // RECARREGAR PRODUTOS
        // =================================================

        await carregarProdutosEstoque();


        // =================================================
        // REAPLICAR INDICADOR "A CAMINHO"
        //
        // Isso garante que após clicar no botão verde
        // a quantidade continue aparecendo imediatamente.
        // =================================================

        if (
            typeof aplicarIndicadoresACaminhoTabela ===
            'function'
        ) {

            setTimeout(
                aplicarIndicadoresACaminhoTabela,
                50
            );

        }


        // =================================================
        // SINCRONIZAÇÃO ML
        // =================================================

        const syncBloqueado =
            produtoSalvo?.bloquear_sync_ml ||
            produtoSalvo?.dados_extra?.bloquear_sync_ml ||
            false;


        if (
            produtoSalvo &&
            produtoSalvo.dados_extra?.mlb_codes?.length &&
            !syncBloqueado
        ) {

            console.log(
                `🔄 Sincronizando produto ${produtoSalvo.sku} com ML (sincronização ATIVA)`
            );


            setTimeout(
                () => {

                    sincronizarEstoqueML(
                        produtoSalvo
                    );

                },
                500
            );

        }

        else if (
            produtoSalvo &&
            produtoSalvo.dados_extra?.mlb_codes?.length &&
            syncBloqueado
        ) {

            console.log(
                `🔒 Produto ${produtoSalvo.sku} com sincronização BLOQUEADA. Não será sincronizado.`
            );


            if (
                podeModificarSync
            ) {

                showToast(
                    '🔒 Sincronização com ML bloqueada para este produto',
                    'info'
                );

            }

        }

    }

    catch (
        error
    ) {

        console.error(
            'Erro ao salvar produto:',
            error
        );


        showToast(
            'Erro: ' +
            error.message,
            'error'
        );

    }
}

