// =========================================================
// GERAR CAMPOS DINÂMICOS
// CATEGORIA + SUBCATEGORIA + ESTOQUE A CAMINHO
// =========================================================

function gerarCamposDinamicos(
    categoria,
    subcategoria = ''
) {

    const container =
        document.getElementById(
            'camposDinamicos'
        );


    if (
        !container
    ) {
        return;
    }


    // =====================================================
    // LIMPAR CAMPOS ANTERIORES
    // =====================================================

    container.innerHTML =
        '';


    // =====================================================
    // CAMPOS EFETIVOS
    // =====================================================

    const campos =
        getCamposPorCategoria(
            categoria,
            subcategoria
        );


    // =====================================================
    // SEM CAMPOS
    // =====================================================

    if (
        !campos ||
        campos.length === 0
    ) {

        container.innerHTML = `

            <div
                class="alert alert-info"
            >
                Nenhum campo específico
                para esta categoria.
            </div>

        `;


        // =============================================
        // ESCONDER BULK
        // =============================================

        const bulkSection =
            document.getElementById(
                'bulkAddSection'
            );


        if (
            bulkSection
        ) {

            bulkSection.style.display =
                'none';

        }


        // =============================================
        // KIT
        // =============================================

        const kitContainer =
            document.getElementById(
                'kitComposicaoContainer'
            );


        if (
            kitContainer
        ) {

            kitContainer.style.display =
                'block';


            if (
                typeof configurarEventosKit ===
                'function'
            ) {

                configurarEventosKit();

            }

        }


        // =============================================
        // REMOVER PAINEL A CAMINHO ANTIGO
        // =============================================

        document
            .getElementById(
                'blocoQuantidadeACaminhoRaios'
            )
            ?.remove();


        return;
    }


    // =====================================================
    // GRID PRINCIPAL
    // =====================================================

    const grid =
        document.createElement(
            'div'
        );


    grid.style.display =
        'grid';


    grid.style.gridTemplateColumns =
        '1fr 1fr';


    grid.style.gap =
        '10px';


    grid.style.marginTop =
        '10px';


    // =====================================================
    // CRIAR CADA CAMPO
    // =====================================================

    campos.forEach(
        campo => {

            if (
                !campo ||
                !campo.nome
            ) {
                return;
            }


            const div =
                document.createElement(
                    'div'
                );


            div.className =
                'campo-dinamico';


            // =================================================
            // SUBCATEGORIA OCUPA DUAS COLUNAS
            // =================================================

            if (
                campo.ehSubcategoria
            ) {

                div.style.gridColumn =
                    '1 / -1';


                div.style.background =
                    '#f5f0ff';


                div.style.border =
                    '1px solid #d2bfff';


                div.style.borderLeft =
                    '4px solid #6f42c1';


                div.style.borderRadius =
                    '7px';


                div.style.padding =
                    '12px';

            }


            // =================================================
            // LABEL
            // =================================================

            const label =
                document.createElement(
                    'label'
                );


            label.style.fontWeight =
                '600';


            label.style.display =
                'block';


            label.style.marginBottom =
                '5px';


            label.textContent =
                `${campo.label || campo.nome} ${
                    campo.obrigatorio
                        ? '*'
                        : ''
                }`;


            div.appendChild(
                label
            );


            // =================================================
            // VALIDAÇÃO NÚMERO COM VÍRGULA
            // =================================================

            if (
                campo.validacao ===
                'numero_virgula'
            ) {

                const input =
                    document.createElement(
                        'input'
                    );


                input.type =
                    'text';


                input.id =
                    `campo_${campo.nome}`;


                input.className =
                    'form-control';


                if (
                    campo.placeholder
                ) {

                    input.placeholder =
                        campo.placeholder;

                }


                if (
                    campo.obrigatorio
                ) {

                    input.required =
                        true;

                }


                input.addEventListener(
                    'input',
                    function() {

                        this.value =
                            this.value.replace(
                                /[^0-9,]/g,
                                ''
                            );

                    }
                );


                input.addEventListener(
                    'blur',
                    function() {

                        const valor =
                            this.value.trim();


                        if (
                            valor !== '' &&
                            !/^[0-9]+(,[0-9]+)?$/.test(
                                valor
                            )
                        ) {

                            showToast(
                                'Digite apenas números e vírgula (ex: 15 ou 15,5)',
                                'warning'
                            );


                            this.focus();

                        }

                    }
                );


                div.appendChild(
                    input
                );


                grid.appendChild(
                    div
                );


                return;
            }


            // =================================================
            // SELECT
            // =================================================

            if (
                campo.tipo ===
                'select'
            ) {

                const select =
                    document.createElement(
                        'select'
                    );


                select.id =
                    `campo_${campo.nome}`;


                select.className =
                    'form-control';


                if (
                    campo.obrigatorio
                ) {

                    select.required =
                        true;

                }


                // =============================================
                // OPÇÃO PADRÃO
                // =============================================

                const defaultOption =
                    document.createElement(
                        'option'
                    );


                defaultOption.value =
                    '';


                if (
                    campo.ehSubcategoria
                ) {

                    defaultOption.textContent =
                        `Sem subcategoria / ${
                            categoria ||
                            'Categoria principal'
                        }`;

                } else {

                    defaultOption.textContent =
                        'Selecione...';

                }


                select.appendChild(
                    defaultOption
                );


                // =============================================
                // OPÇÕES
                // =============================================

                if (
                    Array.isArray(
                        campo.opcoes
                    )
                ) {

                    campo.opcoes.forEach(
                        opcao => {

                            const option =
                                document.createElement(
                                    'option'
                                );


                            option.value =
                                opcao;


                            option.textContent =
                                opcao;


                            select.appendChild(
                                option
                            );

                        }
                    );

                }


                // =============================================
                // SUBCATEGORIA
                // =============================================

                if (
                    campo.ehSubcategoria
                ) {

                    select.value =
                        subcategoria ||
                        '';


                    select.addEventListener(
                        'change',
                        function() {

                            const novaSubcategoria =
                                this.value ||
                                '';


                            console.log(
                                `📂 Categoria: ${categoria} | Subcategoria: ${
                                    novaSubcategoria ||
                                    'sem subcategoria'
                                }`
                            );


                            // =================================
                            // RECRIAR FORMULÁRIO
                            // COM CAMPOS DA SUBCATEGORIA
                            // =================================

                            gerarCamposDinamicos(
                                categoria,
                                novaSubcategoria
                            );

                        }
                    );

                }


                // =============================================
                // MARCA DE RAIOS
                // =============================================

                if (
                    categoria ===
                        'Raios' &&
                    campo.nome ===
                        'marca'
                ) {

                    select.addEventListener(
                        'change',
                        function() {

                            if (
                                typeof atualizarModelosPorMarca ===
                                'function'
                            ) {

                                atualizarModelosPorMarca(
                                    this.value
                                );

                            }

                        }
                    );

                }


                div.appendChild(
                    select
                );


                grid.appendChild(
                    div
                );


                return;
            }


            // =================================================
            // CHECKBOX
            // =================================================

            if (
                campo.tipo ===
                'checkbox'
            ) {

                const wrapper =
                    document.createElement(
                        'div'
                    );


                wrapper.className =
                    'form-check';


                const checkbox =
                    document.createElement(
                        'input'
                    );


                checkbox.type =
                    'checkbox';


                checkbox.id =
                    `campo_${campo.nome}`;


                checkbox.className =
                    'form-check-input';


                const checkLabel =
                    document.createElement(
                        'label'
                    );


                checkLabel.className =
                    'form-check-label';


                checkLabel.htmlFor =
                    `campo_${campo.nome}`;


                checkLabel.textContent =
                    campo.label ||
                    campo.nome;


                wrapper.appendChild(
                    checkbox
                );


                wrapper.appendChild(
                    checkLabel
                );


                div.appendChild(
                    wrapper
                );


                grid.appendChild(
                    div
                );


                return;
            }


            // =================================================
            // TEXTAREA
            // =================================================

            if (
                campo.tipo ===
                'textarea'
            ) {

                const textarea =
                    document.createElement(
                        'textarea'
                    );


                textarea.id =
                    `campo_${campo.nome}`;


                textarea.className =
                    'form-control';


                textarea.rows =
                    campo.rows ||
                    2;


                if (
                    campo.placeholder
                ) {

                    textarea.placeholder =
                        campo.placeholder;

                }


                if (
                    campo.obrigatorio
                ) {

                    textarea.required =
                        true;

                }


                div.appendChild(
                    textarea
                );


                grid.appendChild(
                    div
                );


                return;
            }


            // =================================================
            // INPUT NORMAL / NUMBER
            // =================================================

            const input =
                document.createElement(
                    'input'
                );


            input.type =
                campo.tipo ||
                'text';


            input.id =
                `campo_${campo.nome}`;


            input.className =
                'form-control';


            if (
                campo.step !==
                undefined
            ) {

                input.step =
                    campo.step;

            }


            if (
                campo.min !==
                undefined
            ) {

                input.min =
                    campo.min;

            }


            if (
                campo.max !==
                undefined
            ) {

                input.max =
                    campo.max;

            }


            if (
                campo.placeholder
            ) {

                input.placeholder =
                    campo.placeholder;

            }


            if (
                campo.obrigatorio
            ) {

                input.required =
                    true;

            }


            div.appendChild(
                input
            );


            grid.appendChild(
                div
            );

        }
    );


    // =====================================================
    // COLOCAR GRID
    // =====================================================

    container.appendChild(
        grid
    );


    // =====================================================
    // CAMPOS ESPECIAIS DE ROLAMENTOS
    // =====================================================

    if (
        categoria ===
        'Rolamentos'
    ) {

        let angulosDiv =
            document.getElementById(
                'camposAngulosRolamento'
            );


        if (
            !angulosDiv
        ) {

            angulosDiv =
                document.createElement(
                    'div'
                );


            angulosDiv.id =
                'camposAngulosRolamento';


            angulosDiv.style.display =
                'none';


            angulosDiv.style.marginTop =
                '10px';


            angulosDiv.style.borderTop =
                '1px solid #dee2e6';


            angulosDiv.style.paddingTop =
                '10px';


            angulosDiv.innerHTML = `

                <div
                    style="
                        display:grid;
                        grid-template-columns:
                            1fr 1fr;
                        gap:10px;
                    "
                >

                    <div
                        class="campo-dinamico"
                    >

                        <label
                            style="
                                font-weight:600;
                                display:block;
                                margin-bottom:5px;
                            "
                        >
                            Ângulo interno *
                        </label>


                        <input
                            type="text"
                            id="campo_angulo_interno"
                            class="form-control"
                            placeholder="Ex: 45"
                            required
                        >

                    </div>


                    <div
                        class="campo-dinamico"
                    >

                        <label
                            style="
                                font-weight:600;
                                display:block;
                                margin-bottom:5px;
                            "
                        >
                            Ângulo externo *
                        </label>


                        <input
                            type="text"
                            id="campo_angulo_externo"
                            class="form-control"
                            placeholder="Ex: 45"
                            required
                        >

                    </div>

                </div>


                <small
                    class="text-muted"
                >
                    Preencha os ângulos internos
                    e externos.
                </small>

            `;


            container.appendChild(
                angulosDiv
            );

        }

        function encontrarRegraCondicionalAtiva(campo) {
    const regras =
        normalizarRegrasCondicionaisCampo(
            campo
        );

    for (const regra of regras) {
        const controlador =
            document.getElementById(
                `campo_${regra.campo}`
            );

        if (!controlador) {
            continue;
        }

        const valorAtual =
            obterValorCampoControlador(
                controlador
            );

        const valorEsperado =
            String(
                regra.valor ?? ''
            ).trim();

        if (
            valorAtual.toLocaleLowerCase('pt-BR') ===
            valorEsperado.toLocaleLowerCase('pt-BR')
        ) {
            return regra;
        }
    }

    return null;
}

function obterComportamentoCampoCondicional(campo) {
    const regras =
        normalizarRegrasCondicionaisCampo(
            campo
        );

    if (
        regras.length === 0
    ) {
        return {
            possuiRegras: false,
            regra: null,
            comportamento: 'editavel',
            valorCampo: '',
            obrigatorio: campo?.obrigatorio === true
        };
    }

    const regra =
        encontrarRegraCondicionalAtiva(
            campo
        );

    if (regra) {
        return {
            possuiRegras: true,
            regra,
            comportamento:
                regra.comportamento || 'editavel',
            valorCampo:
                regra.valor_campo ?? '',
            obrigatorio:
                regra.obrigatorio === true
        };
    }

    return {
        possuiRegras: true,
        regra: null,
        comportamento:
            campo.comportamento_padrao_condicional ||
            'ocultar',
        valorCampo: '',
        obrigatorio:
            campo?.obrigatorio === true
    };
}

function aplicarComportamentoCampoCondicional(
    campo
) {
    if (
        !campo?.nome
    ) {
        return;
    }

    const elemento =
        document.getElementById(
            `campo_${campo.nome}`
        );

    if (!elemento) {
        return;
    }

    const container =
        elemento.closest(
            '.campo-dinamico'
        );

    if (!container) {
        return;
    }

    const estado =
        obterComportamentoCampoCondicional(
            campo
        );

    const assinaturaRegra =
        estado.regra
            ? [
                estado.regra.campo,
                estado.regra.valor,
                estado.regra.comportamento,
                estado.regra.valor_campo
            ].join('::')
            : `padrao::${estado.comportamento}`;

    const assinaturaAnterior =
        container.dataset.regraCondicionalAplicada ||
        '';

    const regraMudou =
        assinaturaAnterior !== assinaturaRegra;

    container.dataset.regraCondicionalAplicada =
        assinaturaRegra;

    // Restaurar comportamento básico.
    elemento.disabled = false;
    elemento.readOnly = false;
    elemento.required = false;

    container.style.opacity = '';
    container.style.display = '';

    if (
        estado.comportamento === 'ocultar'
    ) {
        container.style.display = 'none';
        elemento.disabled = true;
        elemento.required = false;

        if (
            elemento.type === 'checkbox'
        ) {
            elemento.checked = false;
        } else {
            elemento.value = '';
        }

        return;
    }

    if (
        estado.comportamento === 'valor_fixo'
    ) {
        container.style.display = '';
        container.style.opacity = '0.85';

        if (
            elemento.type === 'checkbox'
        ) {
            elemento.checked =
                String(
                    estado.valorCampo
                ) === 'true';

            elemento.disabled = true;
        } else {
            elemento.value =
                estado.valorCampo;

            // Select não aceita readonly.
            if (
                elemento.tagName === 'SELECT'
            ) {
                elemento.disabled = true;
            } else {
                elemento.readOnly = true;
            }
        }

        elemento.required =
            estado.obrigatorio;

        return;
    }

    if (
        estado.comportamento ===
        'valor_preenchido'
    ) {
        container.style.display = '';

        if (
            regraMudou &&
            estado.valorCampo !== ''
        ) {
            if (
                elemento.type === 'checkbox'
            ) {
                elemento.checked =
                    String(
                        estado.valorCampo
                    ) === 'true';
            } else {
                elemento.value =
                    estado.valorCampo;
            }
        }

        elemento.required =
            estado.obrigatorio;

        return;
    }

    // Mostrar editável.
    container.style.display = '';

    // Se mudou de uma regra de valor fixo para editável,
    // desbloqueia o campo, mas mantém o valor atual para que
    // o usuário possa confirmar ou alterar.
    elemento.disabled = false;
    elemento.readOnly = false;
    elemento.required =
        estado.obrigatorio;
}


        function obterValorCampoControlador(elemento) {
    if (!elemento) {
        return '';
    }

    if (
        elemento.type === 'checkbox'
    ) {
        return elemento.checked
            ? 'true'
            : 'false';
    }

    return String(
        elemento.value ?? ''
    ).trim();
}

        function obterValorCampoCondicionalProduto(
    elemento
) {

    if (
        !elemento
    ) {

        return '';

    }


    if (
        elemento.type ===
        'checkbox'
    ) {

        return elemento.checked
            ? 'true'
            : 'false';

    }


    return String(
        elemento.value ??
        ''
    ).trim();
}


function condicaoCampoDinamicoAtendida(
    campo
) {

    const condicional =
        campo?.condicional;


    if (
        !condicional ||
        condicional.ativo !==
            true
    ) {

        return true;

    }


    const controlador =
        document.getElementById(
            `campo_${condicional.campo}`
        );


    if (
        !controlador
    ) {

        return false;

    }


    const valorAtual =
        obterValorCampoCondicionalProduto(
            controlador
        );


    const valorEsperado =
        String(
            condicional.valor ??
            ''
        ).trim();


    return (
        valorAtual.toLocaleLowerCase(
            'pt-BR'
        ) ===
        valorEsperado.toLocaleLowerCase(
            'pt-BR'
        )
    );
}


function atualizarVisibilidadeCamposCondicionais(
    categoria,
    subcategoria = ''
) {
    const campos =
        getCamposPorCategoria(
            categoria,
            subcategoria
        ) || [];

    campos.forEach(
        aplicarComportamentoCampoCondicional
    );
}


function configurarEventosCamposCondicionais(
    categoria,
    subcategoria = ''
) {
    const campos =
        getCamposPorCategoria(
            categoria,
            subcategoria
        ) || [];

    const controladores =
        new Set();

    campos.forEach(campo => {
        normalizarRegrasCondicionaisCampo(
            campo
        ).forEach(regra => {
            if (regra?.campo) {
                controladores.add(
                    regra.campo
                );
            }
        });
    });

    controladores.forEach(nomeControlador => {
        const elemento =
            document.getElementById(
                `campo_${nomeControlador}`
            );

        if (!elemento) {
            return;
        }

        const chaveEvento =
            `${categoria}::${subcategoria}`;

        if (
            elemento.dataset
                .eventoCondicionalConfigurado ===
            chaveEvento
        ) {
            return;
        }

        elemento.dataset
            .eventoCondicionalConfigurado =
            chaveEvento;

        const atualizar = function() {
            atualizarVisibilidadeCamposCondicionais(
                categoria,
                subcategoria
            );
        };

        elemento.addEventListener(
            'change',
            atualizar
        );

        elemento.addEventListener(
            'input',
            atualizar
        );
    });

    atualizarVisibilidadeCamposCondicionais(
        categoria,
        subcategoria
    );
}


function validarCamposCondicionaisProduto() {
    const categoria =
        document.getElementById(
            'produtoCategoria'
        )?.value || '';

    const subcategoria =
        document.getElementById(
            'campo_subcategoria'
        )?.value || '';

    const campos =
        getCamposPorCategoria(
            categoria,
            subcategoria
        ) || [];

    for (const campo of campos) {
        if (!campo?.nome) {
            continue;
        }

        const elemento =
            document.getElementById(
                `campo_${campo.nome}`
            );

        if (!elemento) {
            continue;
        }

        const estado =
            obterComportamentoCampoCondicional(
                campo
            );

        if (
            estado.comportamento ===
            'ocultar'
        ) {
            continue;
        }

        if (
            estado.obrigatorio !== true
        ) {
            continue;
        }

        let preenchido;

        if (
            elemento.type === 'checkbox'
        ) {
            preenchido =
                elemento.checked;
        } else {
            preenchido =
                String(
                    elemento.value ?? ''
                ).trim() !== '';
        }

        if (!preenchido) {
            showToast(
                `⚠️ O campo "${campo.label || campo.nome}" é obrigatório.`,
                'warning'
            );

            elemento.focus();

            return false;
        }
    }

    return true;
}

function prepararCamposCondicionaisParaSalvar() {
    const categoria =
        document.getElementById(
            'produtoCategoria'
        )?.value || '';

    const subcategoria =
        document.getElementById(
            'campo_subcategoria'
        )?.value || '';

    const campos =
        getCamposPorCategoria(
            categoria,
            subcategoria
        ) || [];

    campos.forEach(campo => {
        const elemento =
            document.getElementById(
                `campo_${campo.nome}`
            );

        if (!elemento) {
            return;
        }

        const estado =
            obterComportamentoCampoCondicional(
                campo
            );

        // O salvamento original busca o elemento diretamente
        // pelo ID, portanto o valor permanece acessível mesmo
        // quando o select está desabilitado.
        if (
            estado.comportamento ===
            'valor_fixo'
        ) {
            if (
                elemento.type === 'checkbox'
            ) {
                elemento.checked =
                    String(
                        estado.valorCampo
                    ) === 'true';
            } else {
                elemento.value =
                    estado.valorCampo;
            }
        }
    });
}


        // =============================================
        // EXIBIR SOMENTE PARA CAIXA DE DIREÇÃO
        //
        // Mantendo a opção que já existe atualmente
        // em camposPorCategoria.Rolamentos.
        // =============================================

        function toggleAngulos(
            aplicacao
        ) {

            if (
                !angulosDiv
            ) {
                return;
            }


            const deveMostrar =
                aplicacao ===
                'Caixa de Direção';


            angulosDiv.style.display =
                deveMostrar
                    ? 'block'
                    : 'none';


            const interno =
                document.getElementById(
                    'campo_angulo_interno'
                );


            const externo =
                document.getElementById(
                    'campo_angulo_externo'
                );


            if (
                interno
            ) {

                interno.required =
                    deveMostrar;

            }


            if (
                externo
            ) {

                externo.required =
                    deveMostrar;

            }


            if (
                !deveMostrar
            ) {

                if (
                    interno
                ) {

                    interno.value =
                        '';

                }


                if (
                    externo
                ) {

                    externo.value =
                        '';

                }

            }

        }


        const selectAplicacao =
            document.getElementById(
                'campo_aplicaçao'
            );


        if (
            selectAplicacao
        ) {

            selectAplicacao.addEventListener(
                'change',
                function() {

                    toggleAngulos(
                        this.value
                    );

                }
            );


            setTimeout(
                () => {

                    toggleAngulos(
                        selectAplicacao.value
                    );

                },
                0
            );

        }

    }


    // =====================================================
    // KIT DE PRODUTOS
    // =====================================================

    const kitContainer =
        document.getElementById(
            'kitComposicaoContainer'
        );


    if (
        kitContainer
    ) {

        kitContainer.style.display =
            'block';


        if (
            typeof configurarEventosKit ===
            'function'
        ) {

            configurarEventosKit();

        }

    }


    // =====================================================
    // BULK MODE DE RAIOS
    //
    // SOMENTE:
    //
    // Categoria = Raios
    // Subcategoria = nenhuma
    // Produto novo
    //
    // Nipples não abre cadastro múltiplo de tamanhos.
    // =====================================================

    const bulkSection =
        document.getElementById(
            'bulkAddSection'
        );


    const produtoId =
        document.getElementById(
            'produtoId'
        )?.value || '';


    const isEditing =
        produtoId !== '';


    if (
        categoria ===
            'Raios' &&
        !subcategoria &&
        !isEditing
    ) {

        if (
            bulkSection
        ) {

            bulkSection.style.display =
                'block';


            if (
                typeof configurarBulkModeEvents ===
                'function'
            ) {

                configurarBulkModeEvents();

            }

        }

    }

    else {

        if (
            bulkSection
        ) {

            bulkSection.style.display =
                'none';

        }

    }


    // =====================================================
    // ESTOQUE A CAMINHO
    //
    // IMPORTANTE:
    //
    // NÃO sobrescrevemos gerarCamposDinamicos.
    // Apenas acrescentamos o painel depois que todos
    // os campos de categoria/subcategoria já existem.
    // =====================================================

    document
        .getElementById(
            'blocoQuantidadeACaminhoRaios'
        )
        ?.remove();


    if (
    (
        categoria === 'Raios'
        ||
        categoria === 'Parafusos'
    )
    &&
    typeof renderizarBlocoACaminhoRaios ===
        'function'
) {

    setTimeout(
        () => {

            renderizarBlocoACaminhoRaios(
                categoria
            );

        },
        0
    );

}
}

