function atualizarModelosPorMarca(marcaSelecionada) {
    const selectModelo = document.getElementById('campo_modelo');
    if (!selectModelo) return;
    selectModelo.innerHTML = '';
    const optionPadrao = document.createElement('option');
    optionPadrao.value = '';
    optionPadrao.textContent = '-- Selecione um modelo --';
    selectModelo.appendChild(optionPadrao);
    const modelos = modelosPorMarca[marcaSelecionada] || [];
    modelos.forEach(modelo => {
        const option = document.createElement('option');
        option.value = modelo;
        option.textContent = modelo;
        selectModelo.appendChild(option);
    });
}

async function carregarRegrasEstoque() {

    try {

        console.log(
            '🔄 [carregarRegrasEstoque] Iniciando carregamento...'
        );


        window.regrasEstoqueCarregadasGestao =
            false;


        // =====================================================
        // FUNÇÃO INTERNA PARA VALIDAR AS REGRAS
        // =====================================================

        function regrasValidas(
            regras
        ) {

            return (

                regras &&

                typeof regras ===
                    'object' &&

                !Array.isArray(
                    regras
                ) &&

                Object.keys(
                    regras
                ).length > 0

            );
        }


        // =====================================================
        // FUNÇÃO INTERNA PARA LER LOCALSTORAGE
        // =====================================================

        function carregarRegrasLocais() {

            try {

                const localData =
                    localStorage.getItem(
                        'regras_estoque_condicionais'
                    );


                if (
                    !localData
                ) {

                    return null;

                }


                const regras =
                    JSON.parse(
                        localData
                    );


                return regrasValidas(
                    regras
                )
                    ? regras
                    : null;

            } catch (
                error
            ) {

                console.error(
                    '❌ Erro lendo regras locais:',
                    error
                );


                return null;
            }
        }


        // =====================================================
        // SEM SUPABASE
        // =====================================================

        if (
            !window.supabaseClient
        ) {

            console.warn(
                '⚠️ Supabase não disponível. Usando regras locais.'
            );


            const regrasLocais =
                carregarRegrasLocais();


            if (
                regrasLocais
            ) {

                regrasEstoqueAtuais =
                    regrasLocais;

            } else {

                regrasEstoqueAtuais =
                    JSON.parse(
                        JSON.stringify(
                            regrasEstoquePadrao
                        )
                    );


                localStorage.setItem(
                    'regras_estoque_condicionais',
                    JSON.stringify(
                        regrasEstoqueAtuais
                    )
                );

            }


            window.regrasEstoqueCarregadasGestao =
                true;


            await inicializarRegrasCategoriasCustomizadas();


            const modal =
                document.getElementById(
                    'modalRegrasEstoque'
                );


            if (
                modal &&
                modal.style.display ===
                    'flex'
            ) {

                preencherModalRegras();

            }


            return {

                success:
                    true,

                origem:
                    regrasLocais
                        ? 'localStorage'
                        : 'padrao',

                regras:
                    regrasEstoqueAtuais

            };
        }


        // =====================================================
        // BUSCAR CONFIGURAÇÃO NO SUPABASE
        // =====================================================

        const {
            data,
            error
        } =
            await window.supabaseClient
                .from(
                    'configuracoes_sistema'
                )
                .select(
                    '*'
                )
                .eq(
                    'chave',
                    'regras_estoque_condicionais'
                )
                .limit(
                    1
                );


        if (
            error
        ) {

            throw error;

        }


        const configuracao =
            Array.isArray(
                data
            )
                ? data[0]
                : data;


        // =====================================================
        // REGRAS ENCONTRADAS NO BANCO
        // =====================================================

        if (
            configuracao &&
            configuracao.valor
        ) {

            let regrasBanco =
                configuracao.valor;


            if (
                typeof regrasBanco ===
                'string'
            ) {

                regrasBanco =
                    JSON.parse(
                        regrasBanco
                    );

            }


            if (
                !regrasValidas(
                    regrasBanco
                )
            ) {

                throw new Error(
                    'As regras salvas no banco são inválidas.'
                );

            }


            regrasEstoqueAtuais =
                regrasBanco;


            localStorage.setItem(
                'regras_estoque_condicionais',
                JSON.stringify(
                    regrasEstoqueAtuais
                )
            );


            console.log(
                '✅ Regras carregadas do Supabase:',
                regrasEstoqueAtuais
            );

        }

        // =====================================================
        // NÃO EXISTE CONFIGURAÇÃO NO BANCO
        // =====================================================

        else {

            const regrasLocais =
                carregarRegrasLocais();


            if (
                regrasLocais
            ) {

                regrasEstoqueAtuais =
                    regrasLocais;

            } else {

                regrasEstoqueAtuais =
                    JSON.parse(
                        JSON.stringify(
                            regrasEstoquePadrao
                        )
                    );

            }


            const resultadoSalvamento =
                await salvarRegrasEstoque(
                    regrasEstoqueAtuais,
                    true
                );


            if (
                !resultadoSalvamento.success
            ) {

                throw new Error(
                    resultadoSalvamento.error ||
                    'Não foi possível criar a configuração de regras.'
                );

            }

        }


        window.regrasEstoqueCarregadasGestao =
            true;


        await inicializarRegrasCategoriasCustomizadas();


        const modal =
            document.getElementById(
                'modalRegrasEstoque'
            );


        if (
            modal &&
            modal.style.display ===
                'flex'
        ) {

            preencherModalRegras();

        }


        console.log(
            '✅ [carregarRegrasEstoque] Finalizado!'
        );


        return {

            success:
                true,

            origem:
                'supabase',

            regras:
                regrasEstoqueAtuais

        };

    } catch (
        error
    ) {

        console.error(
            '❌ Erro carregando regras do Supabase:',
            error
        );


        // =====================================================
        // FALLBACK LOCAL
        // NÃO SALVA PADRÃO NO BANCO NESTE CASO
        // =====================================================

        let carregouLocal =
            false;


        try {

            const localData =
                localStorage.getItem(
                    'regras_estoque_condicionais'
                );


            if (
                localData
            ) {

                const regrasLocais =
                    JSON.parse(
                        localData
                    );


                if (
                    regrasLocais &&
                    typeof regrasLocais ===
                        'object' &&
                    !Array.isArray(
                        regrasLocais
                    ) &&
                    Object.keys(
                        regrasLocais
                    ).length > 0
                ) {

                    regrasEstoqueAtuais =
                        regrasLocais;


                    carregouLocal =
                        true;

                }

            }

        } catch (
            erroLocal
        ) {

            console.error(
                '❌ Erro carregando regras locais:',
                erroLocal
            );

        }


        if (
            !carregouLocal
        ) {

            regrasEstoqueAtuais =
                JSON.parse(
                    JSON.stringify(
                        regrasEstoquePadrao
                    )
                );

        }


        window.regrasEstoqueCarregadasGestao =
            true;


        await inicializarRegrasCategoriasCustomizadas();


        const modal =
            document.getElementById(
                'modalRegrasEstoque'
            );


        if (
            modal &&
            modal.style.display ===
                'flex'
        ) {

            preencherModalRegras();

        }


        showToast(
            carregouLocal
                ? '⚠️ Banco indisponível. Usando as últimas regras salvas neste navegador.'
                : '⚠️ Banco indisponível. Usando regras padrão temporariamente.',
            'warning'
        );


        return {

            success:
                carregouLocal,

            origem:
                carregouLocal
                    ? 'localStorage'
                    : 'padrao_temporario',

            error:
                error.message,

            regras:
                regrasEstoqueAtuais

        };
    }
}

async function salvarRegrasEstoque(
    regras,
    silencioso = false
) {

    try {

        console.log(
            '🔄 [salvarRegrasEstoque] Salvando regras...'
        );


        if (
            !regras ||
            typeof regras !==
                'object' ||
            Array.isArray(
                regras
            )
        ) {

            throw new Error(
                'Estrutura de regras inválida.'
            );

        }


        const regrasLimpias = {};


        for (
            const [
                categoria,
                dados
            ]
            of Object.entries(
                regras
            )
        ) {

            if (
                !categoria ||
                !dados ||
                !Array.isArray(
                    dados.condicoes
                ) ||
                dados.condicoes.length ===
                    0
            ) {

                console.warn(
                    `⚠️ Categoria ignorada porque não possui condições: ${categoria}`
                );


                continue;
            }


            const condicoesLimpias = [];


            for (
                const condicao
                of dados.condicoes
            ) {

                if (
                    !condicao ||
                    typeof condicao !==
                        'object'
                ) {

                    continue;

                }


                let operador =
                    condicao.operador;


                if (
                    ![
                        'maior_que',
                        'menor_que',
                        'igual_a',
                        'padrao'
                    ].includes(
                        operador
                    )
                ) {

                    operador =
                        'padrao';

                }


                let estoqueMaximo =
                    Number(
                        condicao.estoque_maximo
                    );


                if (
                    !Number.isFinite(
                        estoqueMaximo
                    )
                ) {

                    estoqueMaximo =
                        30;

                }


                estoqueMaximo =
                    Math.max(
                        0,
                        Math.floor(
                            estoqueMaximo
                        )
                    );


                const condicaoLimpa = {

                    operador,

                    estoque_maximo:
                        estoqueMaximo

                };


                if (
                    operador !==
                    'padrao'
                ) {

                    let valor =
                        Number(
                            condicao.valor
                        );


                    if (
                        !Number.isFinite(
                            valor
                        )
                    ) {

                        valor =
                            0;

                    }


                    condicaoLimpa.valor =
                        Math.max(
                            0,
                            valor
                        );

                }


                condicoesLimpias.push(
                    condicaoLimpa
                );

            }


            // =================================================
            // MANTER SOMENTE UMA CONDIÇÃO PADRÃO
            // =================================================

            const condicoesNormais =
                condicoesLimpias.filter(
                    condicao =>
                        condicao.operador !==
                        'padrao'
                );


            let condicaoPadrao =
                condicoesLimpias.find(
                    condicao =>
                        condicao.operador ===
                        'padrao'
                );


            if (
                !condicaoPadrao
            ) {

                condicaoPadrao = {

                    operador:
                        'padrao',

                    estoque_maximo:
                        30

                };

            }


            regrasLimpias[
                categoria
            ] = {

                condicoes: [

                    ...condicoesNormais,

                    condicaoPadrao

                ]

            };

        }


        if (
            Object.keys(
                regrasLimpias
            ).length === 0
        ) {

            throw new Error(
                'Nenhuma regra válida foi encontrada.'
            );

        }


        // =====================================================
        // SALVAR PRIMEIRO NO LOCALSTORAGE
        // =====================================================

        localStorage.setItem(
            'regras_estoque_condicionais',
            JSON.stringify(
                regrasLimpias
            )
        );


        regrasEstoqueAtuais =
            JSON.parse(
                JSON.stringify(
                    regrasLimpias
                )
            );


        // =====================================================
        // SEM SUPABASE
        // =====================================================

        if (
            !window.supabaseClient
        ) {

            console.warn(
                '⚠️ Supabase indisponível. Regras salvas localmente.'
            );


            if (
                !silencioso
            ) {

                showToast(
                    '✅ Regras salvas neste navegador.',
                    'success'
                );

            }


            if (
                typeof renderizarTabelaProdutos ===
                    'function'
            ) {

                renderizarTabelaProdutos(
                    produtosFiltradosAtuais
                );

            }


            return {

                success:
                    true,

                local:
                    true,

                regras:
                    regrasEstoqueAtuais

            };
        }


        // =====================================================
        // VERIFICAR SE CONFIGURAÇÃO JÁ EXISTE
        // =====================================================

        const {
            data: configuracoesExistentes,
            error: erroConsulta
        } =
            await window.supabaseClient
                .from(
                    'configuracoes_sistema'
                )
                .select(
                    'chave'
                )
                .eq(
                    'chave',
                    'regras_estoque_condicionais'
                )
                .limit(
                    1
                );


        if (
            erroConsulta
        ) {

            throw erroConsulta;

        }


        const dadosSalvar = {

            valor:
                JSON.stringify(
                    regrasLimpias
                ),

            atualizado_em:
                new Date()
                    .toISOString(),

            atualizado_por:
                currentUser?.name ||
                currentUser?.username ||
                'sistema'

        };


        let erroSalvamento =
            null;


        if (
            Array.isArray(
                configuracoesExistentes
            ) &&
            configuracoesExistentes.length >
                0
        ) {

            const {
                error
            } =
                await window.supabaseClient
                    .from(
                        'configuracoes_sistema'
                    )
                    .update(
                        dadosSalvar
                    )
                    .eq(
                        'chave',
                        'regras_estoque_condicionais'
                    );


            erroSalvamento =
                error;

        } else {

            const {
                error
            } =
                await window.supabaseClient
                    .from(
                        'configuracoes_sistema'
                    )
                    .insert(
                        {

                            chave:
                                'regras_estoque_condicionais',

                            ...dadosSalvar

                        }
                    );


            erroSalvamento =
                error;

        }


        if (
            erroSalvamento
        ) {

            throw erroSalvamento;

        }


        // Mantém banco e navegador com a mesma versão.
        localStorage.setItem(
            'regras_estoque_condicionais',
            JSON.stringify(
                regrasLimpias
            )
        );


        regrasEstoqueAtuais =
            JSON.parse(
                JSON.stringify(
                    regrasLimpias
                )
            );


        console.log(
            '✅ Regras salvas no banco e no navegador:',
            regrasEstoqueAtuais
        );


        if (
            typeof renderizarTabelaProdutos ===
                'function'
        ) {

            renderizarTabelaProdutos(
                produtosFiltradosAtuais
            );

        }


        if (
            !silencioso
        ) {

            showToast(
                '✅ Regras de estoque atualizadas!',
                'success'
            );

        }


        return {

            success:
                true,

            local:
                false,

            regras:
                regrasEstoqueAtuais

        };

    } catch (
        error
    ) {

        console.error(
            '❌ Erro ao salvar regras:',
            error
        );


        if (
            !silencioso
        ) {

            showToast(
                `❌ Erro ao salvar regras: ${error.message}`,
                'error'
            );

        }


        return {

            success:
                false,

            error:
                error.message

        };
    }
}

function calcularEstoqueMaximo(produto) {
    console.log(`📊 [calcularEstoqueMaximo] INICIANDO - SKU: ${produto.sku}, Preço: ${produto.preco}, Categoria: ${produto.categoria}`);
    
    if (!produto) {
        console.log('📊 Produto vazio, retornando 30');
        return 30;
    }
    
    const sku = produto.sku || '';
    const categoria = produto.categoria || '';
    const precoUnitario = produto.preco || 0;
    
    console.log(`📊 Regras disponíveis no sistema:`, Object.keys(regrasEstoqueAtuais));
    
    // ===== REGRA INDIVIDUAL (prioridade máxima) =====
    const regraIndividual = regrasEstoqueIndividuais[sku];
    if (regraIndividual && regraIndividual.condicoes && regraIndividual.condicoes.length > 0) {
        console.log(`📊 Regra INDIVIDUAL encontrada para SKU: ${sku}`);
        for (const condicao of regraIndividual.condicoes) {
            console.log(`📊 Avaliando condição individual:`, condicao);
            if (condicao.operador === 'padrao') {
                console.log(`📊 Retornando regra individual padrão: ${condicao.estoque_maximo}`);
                return condicao.estoque_maximo || 30;
            }
            if (condicao.operador === 'maior_que' && precoUnitario > condicao.valor) {
                console.log(`📊 Retornando regra individual (preço > ${condicao.valor}): ${condicao.estoque_maximo}`);
                return condicao.estoque_maximo || 30;
            }
            if (condicao.operador === 'menor_que' && precoUnitario < condicao.valor) {
                console.log(`📊 Retornando regra individual (preço < ${condicao.valor}): ${condicao.estoque_maximo}`);
                return condicao.estoque_maximo || 30;
            }
            if (condicao.operador === 'igual_a' && precoUnitario === condicao.valor) {
                console.log(`📊 Retornando regra individual (preço = ${condicao.valor}): ${condicao.estoque_maximo}`);
                return condicao.estoque_maximo || 30;
            }
        }
        // Se não encontrou nenhuma condição, busca o padrão
        const padrao = regraIndividual.condicoes.find(c => c.operador === 'padrao');
        if (padrao) {
            console.log(`📊 Retornando regra individual padrão (fallback): ${padrao.estoque_maximo}`);
            return padrao.estoque_maximo || 30;
        }
    }
    
    // ===== REGRA DA CATEGORIA =====
    console.log(`📊 Buscando regra para categoria: "${categoria}"`);
    console.log(`📊 regrasEstoqueAtuais:`, regrasEstoqueAtuais);
    
    // 🔥 FIX: Verificar se a categoria existe nas regras
    let regrasCategoria = regrasEstoqueAtuais[categoria];
    if (!regrasCategoria) {
        console.log(`📊 Categoria "${categoria}" não encontrada nas regras. Usando 'outros'`);
        regrasCategoria = regrasEstoqueAtuais['outros'] || regrasEstoquePadrao['outros'];
    }
    
    if (!regrasCategoria || !regrasCategoria.condicoes) {
        console.log(`📊 Nenhuma condição encontrada para categoria. Retornando 30`);
        return 30;
    }
    
    console.log(`📊 Condições da categoria "${categoria}":`, regrasCategoria.condicoes);
    
    // Percorre as condições da categoria
    for (const condicao of regrasCategoria.condicoes) {
        console.log(`📊 Avaliando condição:`, condicao);
        
        if (condicao.operador === 'padrao') {
            console.log(`📊 Retornando regra PADRÃO: ${condicao.estoque_maximo}`);
            return condicao.estoque_maximo || 30;
        }
        
        if (condicao.operador === 'maior_que' && precoUnitario > condicao.valor) {
            console.log(`📊 Retornando regra (preço > ${condicao.valor}): ${condicao.estoque_maximo}`);
            return condicao.estoque_maximo || 30;
        }
        
        if (condicao.operador === 'menor_que' && precoUnitario < condicao.valor) {
            console.log(`📊 Retornando regra (preço < ${condicao.valor}): ${condicao.estoque_maximo}`);
            return condicao.estoque_maximo || 30;
        }
        
        if (condicao.operador === 'igual_a' && precoUnitario === condicao.valor) {
            console.log(`📊 Retornando regra (preço = ${condicao.valor}): ${condicao.estoque_maximo}`);
            return condicao.estoque_maximo || 30;
        }
    }
    
    // Se chegou aqui, usa o padrão (última condição ou 30)
    const ultimaCondicao = regrasCategoria.condicoes[regrasCategoria.condicoes.length - 1];
    if (ultimaCondicao) {
        console.log(`📊 Usando última condição como fallback: ${ultimaCondicao.estoque_maximo}`);
        return ultimaCondicao.estoque_maximo || 30;
    }
    
    console.log('📊 Nenhuma regra encontrada, retornando 30');
    return 30;
}

function verificarExcessoEstoque(produto) {
    if (!produto) return false;
    const estoqueMaximo = calcularEstoqueMaximo(produto);
    return produto.quantidade > estoqueMaximo;
}

function getDescricaoRegra(produto) {
    if (!produto || !produto.categoria) return 'Sem regra definida';
    
    const regrasCategoria = regrasEstoqueAtuais[produto.categoria] || regrasEstoquePadrao['outros'];
    if (!regrasCategoria || !regrasCategoria.condicoes) return 'Sem regra definida';
    
    const precoUnitario = produto.preco || 0;
    const regrasAplicadas = [];
    
    for (const condicao of regrasCategoria.condicoes) {
        if (condicao.operador === 'padrao') {
            regrasAplicadas.push(`Padrão: ${condicao.estoque_maximo} unidades`);
            continue;
        }
        
        const operadorTexto = condicao.operador === 'maior_que' ? '>' : 
                             condicao.operador === 'menor_que' ? '<' : '=';
        
        let aplicado = false;
        if (condicao.operador === 'maior_que' && precoUnitario > condicao.valor) aplicado = true;
        else if (condicao.operador === 'menor_que' && precoUnitario < condicao.valor) aplicado = true;
        else if (condicao.operador === 'igual_a' && precoUnitario === condicao.valor) aplicado = true;
        
        const prefixo = aplicado ? '✅' : '⏭️';
        regrasAplicadas.push(`${prefixo} Se preço ${operadorTexto} R$ ${condicao.valor.toFixed(2)} → ${condicao.estoque_maximo} unid.`);
    }
    
    return regrasAplicadas.join('\n');
}

