            const hasSelfService = item.tags?.includes('self_service_in') || 
                                   item.shipping?.tags?.includes('self_service_in');

            console.log(`📦 Item ${itemId}: isFulfillment=${isFulfillment}, hasSelfService=${hasSelfService}`);

