function preencherCamposRegrasFixasTipoAnuncioML() {

    const campoClassico =
        document.getElementById(
            'mlbsFixosClassico'
        );


    const campoPremium =
        document.getElementById(
            'mlbsFixosPremium'
        );


    if (campoClassico) {

        campoClassico.value =
            (
                regrasFixasTipoAnuncioML.classico ||
                []
            ).join('\n');

    }


    if (campoPremium) {

        campoPremium.value =
            (
                regrasFixasTipoAnuncioML.premium ||
                []
            ).join('\n');

    }


    atualizarResumoRegrasFixasTipoAnuncioML();
}


