function adicionarCampoSubcategoria(
    existente = null
) {

    const container =
        document.getElementById(
            'camposNovaSubcategoria'
        );


    if (!container) {
        return;
    }


    const div =
        document.createElement(
            'div'
        );


    div.className =
        'campo-subcategoria-editor';


    div.style.cssText = `

        border:1px solid #dee2e6;
        border-radius:8px;
        padding:12px;
        margin-bottom:10px;
        background:#f8f9fa;

    `;


    div.innerHTML = `

        <div
            style="
                display:grid;
                grid-template-columns:
                    1fr 1fr;
                gap:10px;
            "
        >

            <div>
                <label>Identificador *</label>

                <input
                    class="form-control subcampo-nome"
                    value="${escapeHtml(existente?.nome || '')}"
                    placeholder="Ex: material"
                >
            </div>


            <div>
                <label>Nome exibido *</label>

                <input
                    class="form-control subcampo-label"
                    value="${escapeHtml(existente?.label || '')}"
                    placeholder="Ex: Material"
                >
            </div>


            <div>
                <label>Tipo *</label>

                <select
                    class="form-control subcampo-tipo"
                    onchange="
                        const opcoes =
                            this.closest('.campo-subcategoria-editor')
                                .querySelector('.subcampo-opcoes-wrap');

                        opcoes.style.display =
                            this.value === 'select'
                                ? 'block'
                                : 'none';
                    "
                >

                    <option
                        value="text"
                        ${existente?.tipo === 'text' ? 'selected' : ''}
                    >
                        Texto
                    </option>

                    <option
                        value="number"
                        ${existente?.tipo === 'number' ? 'selected' : ''}
                    >
                        Número
                    </option>

                    <option
                        value="select"
                        ${existente?.tipo === 'select' ? 'selected' : ''}
                    >
                        Seleção
                    </option>

                    <option
                        value="textarea"
                        ${existente?.tipo === 'textarea' ? 'selected' : ''}
                    >
                        Texto Longo
                    </option>

                    <option
                        value="checkbox"
                        ${existente?.tipo === 'checkbox' ? 'selected' : ''}
                    >
                        Sim / Não
                    </option>

                </select>
            </div>


            <div>
                <label>Obrigatório</label>

                <select
                    class="form-control subcampo-obrigatorio"
                >

                    <option
                        value="false"
                        ${!existente?.obrigatorio ? 'selected' : ''}
                    >
                        Não
                    </option>

                    <option
                        value="true"
                        ${existente?.obrigatorio ? 'selected' : ''}
                    >
                        Sim
                    </option>

                </select>
            </div>


            <div>
                <label>Placeholder</label>

                <input
                    class="form-control subcampo-placeholder"
                    value="${escapeHtml(existente?.placeholder || '')}"
                >
            </div>


            <div
                class="subcampo-opcoes-wrap"
                style="
                    ${
                        existente?.tipo ===
                        'select'

                            ? ''

                            : 'display:none;'
                    }
                "
            >

                <label>
                    Opções separadas por vírgula
                </label>

                <input
                    class="form-control subcampo-opcoes"
                    value="${escapeHtml(
                        existente?.opcoes?.join(', ') || ''
                    )}"
                >

            </div>

        </div>


        <div
            style="
                text-align:right;
                margin-top:8px;
            "
        >

            <button
                class="btn btn-sm btn-danger"
                onclick="
                    this.closest('.campo-subcategoria-editor').remove()
                "
            >
                <i class="fas fa-trash"></i>
                Remover
            </button>

        </div>

    `;


    container.appendChild(
        div
    );
}

async function salvarNovaSubcategoria() {

    const categoriaPai =
        document.getElementById(
            'subcategoriaCategoriaPai'
        )?.value;


    const nome =
        document.getElementById(
            'subcategoriaNome'
        )?.value
            ?.trim();


    const herdar =
        document.getElementById(
            'subcategoriaHerdarCampos'
        )?.checked ||
        false;


    if (
        !categoriaPai
    ) {

        showToast(
            'Selecione a categoria pai.',
            'warning'
        );

        return;
    }


    if (
        !nome
    ) {

        showToast(
            'Informe o nome da subcategoria.',
            'warning'
        );

        return;
    }


    const campos = [];


    const linhas =
        document.querySelectorAll(
            '#camposNovaSubcategoria .campo-subcategoria-editor'
        );


    for (
        const linha
        of linhas
    ) {

        const nomeCampo =
            linha.querySelector(
                '.subcampo-nome'
            )?.value
                ?.trim();


        const label =
            linha.querySelector(
                '.subcampo-label'
            )?.value
                ?.trim();


        const tipo =
            linha.querySelector(
                '.subcampo-tipo'
            )?.value ||
            'text';


        const obrigatorio =
            linha.querySelector(
                '.subcampo-obrigatorio'
            )?.value ===
            'true';


        const placeholder =
            linha.querySelector(
                '.subcampo-placeholder'
            )?.value
                ?.trim() ||
            '';


        if (
            !nomeCampo ||
            !label
        ) {

            showToast(
                'Todos os atributos precisam de identificador e nome.',
                'warning'
            );

            return;
        }


        if (
            !/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(
                nomeCampo
            )
        ) {

            showToast(
                `Identificador inválido: ${nomeCampo}`,
                'warning'
            );

            return;
        }


        const campo = {

            nome:
                nomeCampo,

            label,

            tipo,

            obrigatorio,

            placeholder

        };


        if (
            tipo ===
            'select'
        ) {

            const opcoes =
                linha.querySelector(
                    '.subcampo-opcoes'
                )?.value
                    ?.split(',')
                    .map(
                        v =>
                            v.trim()
                    )
                    .filter(Boolean) ||
                [];


            if (
                opcoes.length ===
                0
            ) {

                showToast(
                    `Informe as opções de "${label}".`,
                    'warning'
                );

                return;
            }


            campo.opcoes =
                opcoes;

        }


        if (
            tipo ===
            'textarea'
        ) {

            campo.rows =
                2;

        }


        if (
            tipo ===
            'number'
        ) {

            campo.step =
                '0.01';


            campo.min =
                '0';

        }


        campos.push(
            campo
        );

    }


    // =====================================================
    // MLB CODES AUTOMÁTICO
    // =====================================================

    campos.push({

        nome:
            'mlb_codes',

        label:
            'Códigos MLB',

        tipo:
            'textarea',

        placeholder:
            'MLB separados por vírgula',

        rows:
            2,

        obrigatorio:
            false

    });


    if (
        !subcategoriasEstoque[
            categoriaPai
        ]
    ) {

        subcategoriasEstoque[
            categoriaPai
        ] = {};

    }


    subcategoriasEstoque[
        categoriaPai
    ][nome] = {

        campos,

        herdar_campos_pai:
            herdar,

        criado_por:
            currentUser?.name ||
            'sistema',

        criado_em:
            new Date()
                .toISOString()

    };


    const resultado =
        await salvarSubcategoriasEstoque();


    if (
        !resultado.success
    ) {
        return;
    }


    document.getElementById(
        'subcategoriaNome'
    ).value = '';


    document.getElementById(
        'camposNovaSubcategoria'
    ).innerHTML = '';


    atualizarListaSubcategorias();


    showToast(
        `✅ Subcategoria "${nome}" vinculada a "${categoriaPai}"!`,
        'success'
    );
}

// =========================================================
// ATUALIZAR LISTA DE SUBCATEGORIAS
// =========================================================

function atualizarListaSubcategorias() {

    const container =
        document.getElementById(
            'listaSubcategoriasCadastradas'
        );


    if (!container) {
        return;
    }


    let html = '';


    let quantidadeTotal =
        0;


    Object.entries(
        subcategoriasEstoque ||
        {}
    )
    .sort(
        (
            [categoriaA],
            [categoriaB]
        ) =>
            categoriaA.localeCompare(
                categoriaB,
                'pt-BR'
            )
    )
    .forEach(
        ([
            categoriaPai,
            subcategorias
        ]) => {

            Object.entries(
                subcategorias ||
                {}
            )
            .sort(
                (
                    [nomeA],
                    [nomeB]
                ) =>
                    nomeA.localeCompare(
                        nomeB,
                        'pt-BR'
                    )
            )
            .forEach(
                ([
                    nome,
                    config
                ]) => {

                    quantidadeTotal++;


                    const campos =
                        config.campos ||
                        [];


                    // Não contar MLB como atributo específico
                    const camposEspecificos =
                        campos.filter(
                            campo =>
                                campo.nome !==
                                'mlb_codes'
                        );


                    const herda =
                        !!config
                            .herdar_campos_pai;


                    const produtosUsando =
                        produtosEstoque
                            .filter(
                                produto =>
                                    produto.categoria ===
                                    categoriaPai
                                    &&
                                    produto.dados_extra
                                        ?.subcategoria ===
                                    nome
                            )
                            .length;


                    const listaCampos =
                        camposEspecificos.length

                            ? camposEspecificos
                                .map(
                                    campo => `

                                        <span
                                            style="
                                                background: #e9ecef;
                                                padding: 3px 8px;
                                                border-radius: 4px;
                                                font-size: 10px;
                                                display: inline-block;
                                            "
                                        >

                                            ${escapeHtml(
                                                campo.label ||
                                                campo.nome
                                            )}

                                            ${
                                                campo.obrigatorio
                                                    ? ' *'
                                                    : ''
                                            }

                                        </span>

                                    `
                                )
                                .join('')

                            : `

                                <span
                                    style="
                                        color:#6c757d;
                                        font-size:11px;
                                    "
                                >
                                    Nenhum atributo específico
                                </span>

                            `;


                    html += `

                        <div
                            style="
                                padding: 13px 15px;
                                margin-bottom: 10px;
                                border: 1px solid #d2bfff;
                                border-left: 4px solid #6f42c1;
                                border-radius: 8px;
                                background: #fcfaff;
                            "
                        >

                            <!-- =========================== -->
                            <!-- CABEÇALHO -->
                            <!-- =========================== -->

                            <div
                                style="
                                    display: flex;
                                    justify-content: space-between;
                                    align-items: flex-start;
                                    gap: 10px;
                                "
                            >

                                <div>

                                    <div
                                        style="
                                            font-weight: 700;
                                            font-size: 15px;
                                        "
                                    >

                                        ${escapeHtml(
                                            categoriaPai
                                        )}

                                        <span
                                            style="
                                                color:#6c757d;
                                                margin:0 5px;
                                            "
                                        >
                                            →
                                        </span>

                                        <span
                                            style="
                                                color:#6f42c1;
                                            "
                                        >
                                            ${escapeHtml(
                                                nome
                                            )}
                                        </span>

                                    </div>


                                    <div
                                        style="
                                            display: flex;
                                            gap: 6px;
                                            flex-wrap: wrap;
                                            margin-top: 5px;
                                        "
                                    >

                                        <span
                                            style="
                                                background:#6f42c1;
                                                color:white;
                                                padding:2px 8px;
                                                border-radius:12px;
                                                font-size:9px;
                                            "
                                        >
                                            Subcategoria
                                        </span>


                                        ${
                                            herda

                                                ? `

                                                    <span
                                                        style="
                                                            background:#17a2b8;
                                                            color:white;
                                                            padding:2px 8px;
                                                            border-radius:12px;
                                                            font-size:9px;
                                                        "
                                                    >
                                                        Herda atributos
                                                    </span>

                                                `

                                                : ''
                                        }


                                        <span
                                            style="
                                                background:#e9ecef;
                                                color:#495057;
                                                padding:2px 8px;
                                                border-radius:12px;
                                                font-size:9px;
                                            "
                                        >

                                            ${produtosUsando}
                                            produto(s)

                                        </span>

                                    </div>

                                </div>


                                <!-- ======================= -->
                                <!-- AÇÕES -->
                                <!-- ======================= -->

                                <div
                                    style="
                                        display: flex;
                                        gap: 5px;
                                        flex-shrink: 0;
                                    "
                                >

                                    <button
                                        type="button"
                                        class="btn btn-sm"
                                        style="
                                            background:#6f42c1;
                                            color:white;
                                        "
                                        onclick='editarSubcategoria(
                                            ${JSON.stringify(categoriaPai)},
                                            ${JSON.stringify(nome)}
                                        )'
                                        title="Editar subcategoria"
                                    >

                                        <i class="fas fa-edit"></i>

                                        Editar

                                    </button>


                                    <button
                                        type="button"
                                        class="btn btn-sm btn-danger"
                                        onclick='excluirSubcategoria(
                                            ${JSON.stringify(categoriaPai)},
                                            ${JSON.stringify(nome)}
                                        )'
                                        title="Excluir subcategoria"
                                    >

                                        <i class="fas fa-trash"></i>

                                        Excluir

                                    </button>

                                </div>

                            </div>


                            <!-- =========================== -->
                            <!-- CAMPOS -->
                            <!-- =========================== -->

                            <div
                                style="
                                    margin-top: 10px;
                                    padding-top: 9px;
                                    border-top: 1px solid #eee;
                                "
                            >

                                <div
                                    style="
                                        font-size: 10px;
                                        color:#6c757d;
                                        margin-bottom:5px;
                                    "
                                >
                                    ${camposEspecificos.length}
                                    atributo(s) específico(s)
                                </div>


                                <div
                                    style="
                                        display:flex;
                                        flex-wrap:wrap;
                                        gap:4px;
                                    "
                                >
                                    ${listaCampos}
                                </div>

                            </div>

                        </div>

                    `;

                }
            );

        }
    );


    if (
        quantidadeTotal === 0
    ) {

        html = `

            <div
                style="
                    padding: 30px;
                    text-align: center;
                    color: #6c757d;
                    background: #f8f9fa;
                    border-radius: 8px;
                "
            >

                <i
                    class="fas fa-sitemap"
                    style="
                        font-size: 25px;
                        opacity: .4;
                        display: block;
                        margin-bottom: 8px;
                    "
                ></i>

                Nenhuma subcategoria cadastrada.

            </div>

        `;

    }


    container.innerHTML =
        html;
}

// =========================================================
// EDITAR SUBCATEGORIA
// =========================================================

function editarSubcategoria(
    categoriaPai,
    nome
) {

    const configuracao =
        subcategoriasEstoque
            ?.[categoriaPai]
            ?.[nome];


    if (!configuracao) {

        showToast(
            '❌ Subcategoria não encontrada.',
            'error'
        );

        return;
    }


    // =====================================================
    // DADOS ORIGINAIS
    // =====================================================

    const inputCategoriaOriginal =
        document.getElementById(
            'subcategoriaEditandoCategoriaOriginal'
        );


    const inputNomeOriginal =
        document.getElementById(
            'subcategoriaEditandoNomeOriginal'
        );


    if (
        inputCategoriaOriginal
    ) {

        inputCategoriaOriginal.value =
            categoriaPai;

    }


    if (
        inputNomeOriginal
    ) {

        inputNomeOriginal.value =
            nome;

    }


    // =====================================================
    // PREENCHER FORM
    // =====================================================

    const selectCategoria =
        document.getElementById(
            'subcategoriaCategoriaPai'
        );


    const inputNome =
        document.getElementById(
            'subcategoriaNome'
        );


    const checkHerdar =
        document.getElementById(
            'subcategoriaHerdarCampos'
        );


    if (
        selectCategoria
    ) {

        selectCategoria.value =
            categoriaPai;

    }


    if (
        inputNome
    ) {

        inputNome.value =
            nome;

    }


    if (
        checkHerdar
    ) {

        checkHerdar.checked =
            !!configuracao
                .herdar_campos_pai;

    }


    // =====================================================
    // LIMPAR CAMPOS
    // =====================================================

    const container =
        document.getElementById(
            'camposNovaSubcategoria'
        );


    if (
        container
    ) {

        container.innerHTML =
            '';

    }


    // =====================================================
    // CARREGAR CAMPOS
    //
    // MLB Codes não entra no editor porque é automático.
    // =====================================================

    const campos =
        configuracao.campos ||
        [];


    campos.forEach(
        campo => {

            if (
                campo.nome ===
                'mlb_codes'
            ) {

                return;

            }


            adicionarCampoSubcategoria(
                campo
            );

        }
    );


    // =====================================================
    // CABEÇALHO
    // =====================================================

    const titulo =
        document.getElementById(
            'tituloModalSubcategoria'
        );


    if (
        titulo
    ) {

        titulo.innerHTML = `

            <i class="fas fa-edit"></i>

            Editar Subcategoria

        `;

    }


    const info =
        document.getElementById(
            'infoModoEdicaoSubcategoria'
        );


    if (
        info
    ) {

        info.style.display =
            'block';


        info.innerHTML = `

            Editando:

            <strong>
                ${escapeHtml(categoriaPai)}
                →
                ${escapeHtml(nome)}
            </strong>

        `;

    }


    // =====================================================
    // BOTÃO SALVAR
    // =====================================================

    const btnSalvar =
        document.getElementById(
            'btnSalvarSubcategoria'
        );


    if (
        btnSalvar
    ) {

        btnSalvar.className =
            'btn btn-primary';


        btnSalvar.innerHTML = `

            <i class="fas fa-save"></i>

            Atualizar Subcategoria

        `;


        btnSalvar.onclick =
            atualizarSubcategoriaExistente;

    }


    // =====================================================
    // CANCELAR EDIÇÃO
    // =====================================================

    const btnCancelar =
        document.getElementById(
            'btnCancelarEdicaoSubcategoria'
        );


    if (
        btnCancelar
    ) {

        btnCancelar.style.display =
            'inline-block';

    }


    // =====================================================
    // SUBIR MODAL PARA O TOPO
    // =====================================================

    const modal =
        document.getElementById(
            'modalGerenciarSubcategorias'
        );


    const conteudo =
        modal?.querySelector(
            'div'
        );


    if (
        conteudo
    ) {

        conteudo.scrollTop =
            0;

    }


    document.getElementById(
        'subcategoriaNome'
    )?.focus();


    console.log(
        `✏️ Editando subcategoria ${categoriaPai} → ${nome}`
    );
}

// =========================================================
// ATUALIZAR SUBCATEGORIA EXISTENTE
// =========================================================

async function atualizarSubcategoriaExistente() {

    const categoriaPaiOriginal =
        document.getElementById(
            'subcategoriaEditandoCategoriaOriginal'
        )?.value;


    const nomeOriginal =
        document.getElementById(
            'subcategoriaEditandoNomeOriginal'
        )?.value;


    const categoriaPaiNova =
        document.getElementById(
            'subcategoriaCategoriaPai'
        )?.value;


    const nomeNovo =
        document.getElementById(
            'subcategoriaNome'
        )?.value
            ?.trim();


    const herdar =
        document.getElementById(
            'subcategoriaHerdarCampos'
        )?.checked ||
        false;


    // =====================================================
    // VALIDAR ORIGINAL
    // =====================================================

    if (
        !categoriaPaiOriginal ||
        !nomeOriginal
    ) {

        showToast(
            '❌ Não foi possível identificar a subcategoria original.',
            'error'
        );

        return;
    }


    if (
        !subcategoriasEstoque
            ?.[categoriaPaiOriginal]
            ?.[nomeOriginal]
    ) {

        showToast(
            '❌ A subcategoria original não existe mais.',
            'error'
        );

        return;
    }


    // =====================================================
    // VALIDAR NOVOS DADOS
    // =====================================================

    if (
        !categoriaPaiNova
    ) {

        showToast(
            '⚠️ Selecione a categoria pai.',
            'warning'
        );

        return;
    }


    if (
        !nomeNovo
    ) {

        showToast(
            '⚠️ Informe o nome da subcategoria.',
            'warning'
        );

        return;
    }


    // =====================================================
    // NÃO PERMITIR DUPLICAR
    // =====================================================

    const mudouIdentidade =
        categoriaPaiNova !==
        categoriaPaiOriginal
        ||
        nomeNovo !==
        nomeOriginal;


    if (
        mudouIdentidade &&
        subcategoriasEstoque
            ?.[categoriaPaiNova]
            ?.[nomeNovo]
    ) {

        showToast(
            `⚠️ Já existe "${categoriaPaiNova} → ${nomeNovo}".`,
            'warning'
        );

        return;
    }


    // =====================================================
    // COLETAR CAMPOS
    // =====================================================

    const campos =
        [];


    const linhas =
        document.querySelectorAll(
            '#camposNovaSubcategoria .campo-subcategoria-editor'
        );


    for (
        const linha
        of linhas
    ) {

        const nomeCampo =
            linha.querySelector(
                '.subcampo-nome'
            )?.value
                ?.trim();


        const label =
            linha.querySelector(
                '.subcampo-label'
            )?.value
                ?.trim();


        const tipo =
            linha.querySelector(
                '.subcampo-tipo'
            )?.value ||
            'text';


        const obrigatorio =
            linha.querySelector(
                '.subcampo-obrigatorio'
            )?.value ===
            'true';


        const placeholder =
            linha.querySelector(
                '.subcampo-placeholder'
            )?.value
                ?.trim() ||
            '';


        // =============================================
        // VALIDAÇÃO
        // =============================================

        if (
            !nomeCampo ||
            !label
        ) {

            showToast(
                '⚠️ Todos os atributos precisam de identificador e nome.',
                'warning'
            );

            return;
        }


        if (
            !/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(
                nomeCampo
            )
        ) {

            showToast(
                `⚠️ Identificador inválido: ${nomeCampo}`,
                'warning'
            );

            return;
        }


        if (
            campos.some(
                campo =>
                    campo.nome ===
                    nomeCampo
            )
        ) {

            showToast(
                `⚠️ O atributo "${nomeCampo}" está duplicado.`,
                'warning'
            );

            return;
        }


        const campo = {

            nome:
                nomeCampo,

            label,

            tipo,

            obrigatorio,

            placeholder

        };


        // =============================================
        // SELECT
        // =============================================

        if (
            tipo ===
            'select'
        ) {

            const opcoes =
                linha.querySelector(
                    '.subcampo-opcoes'
                )?.value
                    ?.split(',')
                    .map(
                        valor =>
                            valor.trim()
                    )
                    .filter(Boolean) ||
                [];


            if (
                opcoes.length ===
                0
            ) {

                showToast(
                    `⚠️ Informe as opções de "${label}".`,
                    'warning'
                );

                return;
            }


            campo.opcoes =
                opcoes;

        }


        // =============================================
        // TEXTAREA
        // =============================================

        if (
            tipo ===
            'textarea'
        ) {

            campo.rows =
                2;

        }


        // =============================================
        // NUMBER
        // =============================================

        if (
            tipo ===
            'number'
        ) {

            campo.step =
                '0.01';


            campo.min =
                '0';

        }


        campos.push(
            campo
        );

    }


    // =====================================================
    // MLB AUTOMÁTICO
    // =====================================================

    campos.push({

        nome:
            'mlb_codes',

        label:
            'Códigos MLB',

        tipo:
            'textarea',

        placeholder:
            'MLB separados por vírgula',

        rows:
            2,

        obrigatorio:
            false

    });


    // =====================================================
    // CONFIGURAÇÃO ANTIGA
    // =====================================================

    const configAntiga =
        subcategoriasEstoque[
            categoriaPaiOriginal
        ][
            nomeOriginal
        ];


    const configNova = {

        ...configAntiga,

        campos,

        herdar_campos_pai:
            herdar,

        atualizado_por:
            currentUser?.name ||
            'sistema',

        atualizado_em:
            new Date()
                .toISOString()

    };


    // =====================================================
    // SE MUDOU CATEGORIA PAI OU NOME
    // =====================================================

    if (
        mudouIdentidade
    ) {

        // =============================================
        // CRIAR DESTINO
        // =============================================

        if (
            !subcategoriasEstoque[
                categoriaPaiNova
            ]
        ) {

            subcategoriasEstoque[
                categoriaPaiNova
            ] = {};

        }


        subcategoriasEstoque[
            categoriaPaiNova
        ][
            nomeNovo
        ] =
            configNova;


        // =============================================
        // REMOVER ANTIGA
        // =============================================

        delete subcategoriasEstoque[
            categoriaPaiOriginal
        ][
            nomeOriginal
        ];


        if (
            Object.keys(
                subcategoriasEstoque[
                    categoriaPaiOriginal
                ]
            ).length ===
            0
        ) {

            delete subcategoriasEstoque[
                categoriaPaiOriginal
            ];

        }

    } else {

        // =============================================
        // MESMA IDENTIDADE
        // =============================================

        subcategoriasEstoque[
            categoriaPaiOriginal
        ][
            nomeOriginal
        ] =
            configNova;

    }


    // =====================================================
    // SALVAR CONFIGURAÇÃO
    // =====================================================

    const resultado =
        await salvarSubcategoriasEstoque();


    if (
        !resultado.success
    ) {
        return;
    }


    // =====================================================
    // ATUALIZAR PRODUTOS CASO NOME/CATEGORIA TENHA MUDADO
    //
    // Ex:
    // Raios → Nipples
    //
    // vira:
    // Raios → Niples
    //
    // Todos os produtos existentes precisam acompanhar.
    // =====================================================

    if (
        mudouIdentidade
    ) {

        const produtosAfetados =
            produtosEstoque.filter(
                produto =>
                    produto.categoria ===
                    categoriaPaiOriginal
                    &&
                    produto.dados_extra
                        ?.subcategoria ===
                    nomeOriginal
            );


        console.log(
            `🔄 ${produtosAfetados.length} produto(s) precisam migrar de subcategoria.`
        );


        for (
            const produto
            of produtosAfetados
        ) {

            try {

                const dadosExtraNovo = {

                    ...(
                        produto.dados_extra ||
                        {}
                    ),

                    subcategoria:
                        nomeNovo

                };


                const atualizacao = {

                    dados_extra:
                        dadosExtraNovo

                };


                // =========================================
                // SE MUDOU A CATEGORIA PAI
                // =========================================

                if (
                    categoriaPaiNova !==
                    categoriaPaiOriginal
                ) {

                    atualizacao.categoria =
                        categoriaPaiNova;

                }


                const {
                    error
                } =
                    await window.supabaseClient
                        .from(
                            'produtos_estoque'
                        )
                        .update(
                            atualizacao
                        )
                        .eq(
                            'id',
                            produto.id
                        );


                if (
                    error
                ) {
                    throw error;
                }


                // Atualizar memória
                produto.dados_extra =
                    dadosExtraNovo;


                if (
                    categoriaPaiNova !==
                    categoriaPaiOriginal
                ) {

                    produto.categoria =
                        categoriaPaiNova;

                }


            } catch (error) {

                console.error(
                    `❌ Erro migrando produto ${produto.sku}:`,
                    error
                );

            }

        }

    }


    // =====================================================
    // RECARREGAR PRODUTOS
    // =====================================================

    try {

        await carregarProdutosEstoque();

    } catch (error) {

        console.warn(
            '⚠️ Não foi possível recarregar produtos:',
            error
        );

    }


    // =====================================================
    // VOLTAR PARA MODO NOVO
    // =====================================================

    cancelarEdicaoSubcategoria();


    atualizarListaSubcategorias();


    showToast(
        `✅ Subcategoria "${categoriaPaiNova} → ${nomeNovo}" atualizada!`,
        'success'
    );
}

// =========================================================
// CANCELAR EDIÇÃO / VOLTAR PARA NOVA SUBCATEGORIA
// =========================================================

function cancelarEdicaoSubcategoria() {

    const categoriaOriginal =
        document.getElementById(
            'subcategoriaEditandoCategoriaOriginal'
        );


    const nomeOriginal =
        document.getElementById(
            'subcategoriaEditandoNomeOriginal'
        );


    if (
        categoriaOriginal
    ) {

        categoriaOriginal.value =
            '';

    }


    if (
        nomeOriginal
    ) {

        nomeOriginal.value =
            '';

    }


    // =====================================================
    // LIMPAR FORM
    // =====================================================

    const categoria =
        document.getElementById(
            'subcategoriaCategoriaPai'
        );


    const nome =
        document.getElementById(
            'subcategoriaNome'
        );


    const herdar =
        document.getElementById(
            'subcategoriaHerdarCampos'
        );


    const campos =
        document.getElementById(
            'camposNovaSubcategoria'
        );


    if (
        categoria
    ) {
        categoria.value = '';
    }


    if (
        nome
    ) {
        nome.value = '';
    }


    if (
        herdar
    ) {
        herdar.checked = false;
    }


    if (
        campos
    ) {
        campos.innerHTML = '';
    }


    // =====================================================
    // TÍTULO
    // =====================================================

    const titulo =
        document.getElementById(
            'tituloModalSubcategoria'
        );


    if (
        titulo
    ) {

        titulo.innerHTML = `

            <i class="fas fa-sitemap"></i>

            Gerenciar Subcategorias

        `;

    }


    const info =
        document.getElementById(
            'infoModoEdicaoSubcategoria'
        );


    if (
        info
    ) {

        info.style.display =
            'none';


        info.innerHTML =
            '';

    }


    // =====================================================
    // BOTÃO
    // =====================================================

    const btnSalvar =
        document.getElementById(
            'btnSalvarSubcategoria'
        );


    if (
        btnSalvar
    ) {

        btnSalvar.className =
            'btn btn-success';


        btnSalvar.innerHTML = `

            <i class="fas fa-save"></i>

            Salvar Subcategoria

        `;


        btnSalvar.onclick =
            salvarNovaSubcategoria;

    }


    const btnCancelar =
        document.getElementById(
            'btnCancelarEdicaoSubcategoria'
        );


    if (
        btnCancelar
    ) {

        btnCancelar.style.display =
            'none';

    }
}


async function excluirSubcategoria(
    categoriaPai,
    nome
) {

    // =====================================================
    // VERIFICAR SE TEM PRODUTOS USANDO
    // =====================================================

    const produtosUsando =
        produtosEstoque.filter(
            produto =>
                produto.categoria ===
                categoriaPai
                &&
                produto.dados_extra
                    ?.subcategoria ===
                nome
        );


    if (
        produtosUsando.length >
        0
    ) {

        showToast(
            `❌ Não é possível excluir "${nome}". Existem ${produtosUsando.length} produto(s) usando esta subcategoria.`,
            'error'
        );

        return;
    }


    if (
        !confirm(
            `Excluir a subcategoria "${categoriaPai} → ${nome}"?`
        )
    ) {

        return;
    }


    delete subcategoriasEstoque[
        categoriaPai
    ][nome];


    if (
        Object.keys(
            subcategoriasEstoque[
                categoriaPai
            ]
        ).length === 0
    ) {

        delete subcategoriasEstoque[
            categoriaPai
        ];

    }


    await salvarSubcategoriasEstoque();


    atualizarListaSubcategorias();


    showToast(
        `✅ Subcategoria "${nome}" excluída.`,
        'success'
    );
}


