function adicionarBotaoCriarCategoria() {

    console.log(
        '🔧 [adicionarBotaoCriarCategoria] Preparando item no menu...'
    );


    // =====================================================
    // JÁ EXISTE?
    // =====================================================

    const existente =
        document.getElementById(
            'btnCriarCategoria'
        );


    if (existente) {

        const menu =
            garantirMenuAcessibilidadeEstoque();


        if (
            menu &&
            existente.parentElement !==
            menu
        ) {

            estilizarItemMenuAcessibilidadeEstoque(
                existente
            );


            menu.appendChild(
                existente
            );

        }


        return;
    }


    // =====================================================
    // MENU
    // =====================================================

    const menu =
        garantirMenuAcessibilidadeEstoque();


    if (!menu) {

        setTimeout(
            adicionarBotaoCriarCategoria,
            500
        );


        return;
    }


    // =====================================================
    // PERMISSÃO
    // =====================================================

    const username =
        currentUser?.username
            ?.toLowerCase() || '';


    const isAuthorized =
        usuariosGerenciarCategorias.includes(
            username
        );


    // =====================================================
    // CRIAR
    // =====================================================

    const btn =
        document.createElement(
            'button'
        );


    btn.id =
        'btnCriarCategoria';


    btn.type =
        'button';


    btn.innerHTML = `

        <i class="fas fa-plus-circle"></i>

        Criar Categoria

    `;


    btn.title =
        'Criar nova categoria personalizada com campos específicos';


    btn.onclick =
        abrirModalCriarCategoria;


    if (!isAuthorized) {

        btn.disabled =
            true;


        btn.title =
            '🔒 Apenas usuários autorizados podem criar categorias';


        btn.style.opacity =
            '0.6';


        btn.style.cursor =
            'not-allowed';

    }


    estilizarItemMenuAcessibilidadeEstoque(
        btn
    );


    // Restaurar aparência de bloqueado depois
    // da estilização.
    if (!isAuthorized) {

        btn.style.opacity =
            '0.5';


        btn.style.cursor =
            'not-allowed';

    }


    menu.appendChild(
        btn
    );


    console.log(
        '✅ Criar Categoria adicionado ao menu Acessibilidade!'
    );
}

// ===== ABRIR MODAL DE CRIAÇÃO DE CATEGORIA =====
function abrirModalCriarCategoria() {
    const username = currentUser?.username?.toLowerCase() || '';
    const isAuthorized = usuariosGerenciarCategorias.includes(username);
    
    if (!isAuthorized) {
        showToast('⚠️ Apenas usuários autorizados podem criar categorias.', 'warning');
        return;
    }
    
    let modal = document.getElementById('modalCriarCategoria');
    if (!modal) {
        modal = criarModalCriarCategoria();
    }
    
    document.getElementById('novaCategoriaNome').value = '';
    document.getElementById('novaCategoriaNome').disabled = false;
    document.getElementById('novaCategoriaCampos').innerHTML = '';
    
    adicionarCampoPadraoMLB();
    
    const btnSalvar = document.querySelector('#modalCriarCategoria .btn-success');
    if (btnSalvar) {
        btnSalvar.textContent = 'Criar Categoria';
        btnSalvar.onclick = salvarNovaCategoria;
    }
    
    modal.classList.remove('hidden');
    modal.style.display = 'flex';
}

