// =========================================================
// BAIXAR RELATÓRIO EM EXCEL
// =========================================================

function baixarRelatorioImportacaoML() {

    const resultado =
        resultadoImportacaoPlanilhaML;


    if (!resultado) {

        showToast(
            'Nenhum relatório disponível.',
            'warning'
        );

        return;

    }


    if (
        typeof XLSX ===
        'undefined'
    ) {

        showToast(
            'Biblioteca XLSX não disponível.',
            'error'
        );

        return;

    }


    const wb =
        XLSX.utils.book_new();


    // =====================================================
    // RESUMO
    // =====================================================

    const resumo = [

        [
            'Campo',
            'Valor'
        ],

        [
            'Arquivo',
            resultado.arquivo
        ],

        [
            'Aba',
            resultado.aba
        ],

        [
            'Linhas do arquivo',
            resultado.resumo.linhasArquivo
        ],

        [
            'Linhas analisadas',
            resultado.resumo.linhasAnalisadas
        ],

        [
            'Linhas ignoradas',
            resultado.resumo.linhasIgnoradas
        ],

        [
            'MLBs únicos',
            resultado.resumo.mlbsUnicos
        ],

        [
            'Produtos encontrados',
            resultado.resumo.produtosEncontrados
        ],

        [
            'Linhas de kit',
            resultado.resumo.linhasKit
        ],

        [
            'MLBs adicionados',
            resultado.resumo.mlbsAdicionar
        ],

        [
            'Kits adicionados',
            resultado.resumo.kitsAdicionar
        ],

        [
            'Kits corrigidos',
            resultado.resumo.kitsAtualizar
        ],

        [
            'Erros encontrados',
            resultado.erros.length
        ],

        [
            'Ajustes aplicados',
            resultado.aplicados.length
        ],

        [
            'Erros de gravação',
            resultado.errosAplicacao.length
        ]

    ];


    const wsResumo =
        XLSX.utils.aoa_to_sheet(
            resumo
        );


    XLSX.utils.book_append_sheet(
        wb,
        wsResumo,
        'Resumo'
    );


    // =====================================================
    // AJUSTES
    // =====================================================

    const ajustes =
        resultado.aplicados.map(
            item => ({

                Tipo:
                    item.tipo,

                SKU:
                    item.sku,

                Alteração:
                    item.descricao,

                Resultado:
                    item.resultado

            })
        );


    const wsAjustes =
        XLSX.utils.json_to_sheet(
            ajustes.length
                ? ajustes
                : [
                    {
                        Tipo:
                            'Nenhum ajuste necessário'
                    }
                ]
        );


    XLSX.utils.book_append_sheet(
        wb,
        wsAjustes,
        'Ajustes'
    );


    // =====================================================
    // ERROS
    // =====================================================

    const erros =
        resultado.erros.map(
            item => ({

                Linha:
                    item.linha,

                Tipo:
                    item.tipo,

                MLB:
                    item.mlb,

                'SKU Planilha':
                    item.skuPlanilha,

                Componente:
                    item.componente,

                Base:
                    item.base,

                Descrição:
                    item.descricao,

                Ação:
                    item.acao

            })
        );


    const wsErros =
        XLSX.utils.json_to_sheet(
            erros.length
                ? erros
                : [
                    {
                        Resultado:
                            'Nenhum erro encontrado'
                    }
                ]
        );


    XLSX.utils.book_append_sheet(
        wb,
        wsErros,
        'Erros'
    );


    // =====================================================
    // AVISOS
    // =====================================================

    const avisos =
        resultado.avisos.map(
            item => ({

                Linha:
                    item.linha,

                Tipo:
                    item.tipo,

                MLB:
                    item.mlb,

                SKU:
                    item.sku,

                Descrição:
                    item.descricao

            })
        );


    const wsAvisos =
        XLSX.utils.json_to_sheet(
            avisos.length
                ? avisos
                : [
                    {
                        Resultado:
                            'Nenhum aviso'
                    }
                ]
        );


    XLSX.utils.book_append_sheet(
        wb,
        wsAvisos,
        'Avisos'
    );


    // =====================================================
    // PRODUTOS SEM OCORRÊNCIA NA PLANILHA
    // =====================================================

    const wsSemPlanilha =
        XLSX.utils.json_to_sheet(

            resultado
                .produtosSemPlanilha
                .map(
                    p => ({

                        SKU:
                            p.sku,

                        Produto:
                            p.nome,

                        ID:
                            p.id

                    })
                )

        );


    XLSX.utils.book_append_sheet(
        wb,
        wsSemPlanilha,
        'Sem ocorrência'
    );


    const agora =
        new Date();


    const dataNome =
        `${agora.getFullYear()}-${String(
            agora.getMonth() + 1
        ).padStart(2, '0')}-${String(
            agora.getDate()
        ).padStart(2, '0')}`;


    XLSX.writeFile(

        wb,

        `relatorio_importacao_ml_${dataNome}.xlsx`

    );
}


