// =========================================================
// DESATIVAR IMPORTADOR DEPOIS QUE TERMINAR TUDO
// =========================================================

async function desativarImportadorCadastroInicial() {

    const confirmar =
        confirm(
            'Desativar o Importador de Produtos?\n\nFaça isso somente depois que terminar toda a carga inicial. O botão desaparecerá da Gestão de Estoque.'
        );


    if (!confirmar) {
        return;
    }


    try {

        const {
            error
        } =
            await window.supabaseClient
                .from(
                    'configuracoes_sistema'
                )
                .upsert({

                    chave:
                        'importador_cadastro_inicial_ativo',

                    valor:
                        JSON.stringify(
                            false
                        ),

                    atualizado_em:
                        new Date()
                            .toISOString(),

                    atualizado_por:
                        currentUser?.name ||
                        'sistema'

                }, {

                    onConflict:
                        'chave'

                });


        if (error) {
            throw error;
        }


        document
            .getElementById(
                'btnImportarCadastroInicial'
            )
            ?.remove();


        fecharPreviaCadastroInicial();


        showToast(
            '✅ Importador de cadastro inicial desativado.',
            'success'
        );


    } catch (error) {

        console.error(
            'Erro desativando importador:',
            error
        );


        showToast(
            `Erro ao desativar importador: ${error.message}`,
            'error'
        );

    }
}


async function adicionarBotaoImportacaoCadastroInicial() {

    // =====================================================
    // JÁ EXISTE?
    // =====================================================

    const existente =
        document.getElementById(
            'btnImportarCadastroInicial'
        );


    if (existente) {

        const menu =
            garantirMenuAcessibilidadeEstoque();


        if (
            menu &&
            existente.parentElement !==
            menu
        ) {

            estilizarItemMenuAcessibilidadeEstoque(
                existente
            );


            menu.appendChild(
                existente
            );

        }


        return;
    }


    // =====================================================
    // IMPORTADOR ATIVO?
    // =====================================================

    const ativo =
        await importadorCadastroInicialEstaAtivo();


    if (!ativo) {

        console.log(
            'ℹ️ Importador de cadastro inicial está desativado.'
        );


        return;
    }


    // =====================================================
    // SOMENTE ADMIN
    // =====================================================

    const username =
        currentUser?.username
            ?.toLowerCase() || '';


    if (
        !usuariosAdmin.includes(
            username
        )
    ) {

        return;
    }


    // =====================================================
    // GARANTIR MENU
    // =====================================================

    const menu =
        garantirMenuAcessibilidadeEstoque();


    if (!menu) {

        setTimeout(
            adicionarBotaoImportacaoCadastroInicial,
            500
        );


        return;
    }


    // =====================================================
    // CRIAR
    // =====================================================

    const botao =
        document.createElement(
            'button'
        );


    botao.id =
        'btnImportarCadastroInicial';


    botao.type =
        'button';


    botao.innerHTML = `

        <i class="fas fa-box-open"></i>

        Importar Produtos

    `;


    botao.title =
        'Importação temporária do cadastro inicial de produtos';


    botao.onclick =
        abrirImportacaoCadastroInicial;


    estilizarItemMenuAcessibilidadeEstoque(
        botao
    );


    menu.appendChild(
        botao
    );
}

