// =========================================================
// FORMATAR DATA BR
// =========================================================

function formatarDataRastreioBR(
    data
) {

    if (!data) {
        return '-';
    }


    try {

        const partes =
            String(data)
                .substring(
                    0,
                    10
                )
                .split('-');


        if (
            partes.length === 3
        ) {

            return (
                partes[2] +
                '/' +
                partes[1] +
                '/' +
                partes[0]
            );

        }


        return new Date(
            data
        ).toLocaleDateString(
            'pt-BR'
        );


    } catch (error) {

        return String(
            data
        );

    }
}


// =========================================================
// CALCULAR PREVISÃO
// =========================================================

function calcularPrevisaoRastreioCompra(
    dias
) {

    const quantidadeDias =
        Math.max(
            1,
            parseInt(
                dias
            ) || 14
        );


    const hoje =
        new Date();


    const previsao =
        new Date(

            hoje.getFullYear(),

            hoje.getMonth(),

            hoje.getDate() +
                quantidadeDias,

            12,
            0,
            0

        );


    const ano =
        previsao
            .getFullYear();


    const mes =
        String(
            previsao.getMonth() +
            1
        ).padStart(
            2,
            '0'
        );


    const dia =
        String(
            previsao.getDate()
        ).padStart(
            2,
            '0'
        );


    return `${ano}-${mes}-${dia}`;
}


// =========================================================
// CONVERTER VALOR BRASILEIRO
// =========================================================

function converterValorCompraRastreio(
    valor
) {

    let texto =
        String(
            valor ?? ''
        )
        .trim()
        .replace(
            /R\$/gi,
            ''
        )
        .replace(
            /\s/g,
            ''
        );


    if (!texto) {
        return 0;
    }


    if (
        texto.includes(',') &&
        texto.includes('.')
    ) {

        texto =
            texto
                .replace(
                    /\./g,
                    ''
                )
                .replace(
                    ',',
                    '.'
                );

    }

    else if (
        texto.includes(',')
    ) {

        texto =
            texto.replace(
                ',',
                '.'
            );

    }


    const numero =
        Number(
            texto
        );


    return Number.isFinite(
        numero
    )
        ? numero
        : 0;
}


// =========================================================
// PARSE DOS DADOS DO CARD
// =========================================================

function obterMetadadosRastreioCard(
    card
) {

    if (!card) {
        return {};
    }


    const bruto =
        card.dados_brutos;


    if (!bruto) {
        return {};
    }


    if (
        typeof bruto ===
        'object'
    ) {

        return bruto;

    }


    try {

        return JSON.parse(
            bruto
        );

    } catch (error) {

        return {};

    }
}


// =========================================================
// CARREGAR PRÉ-ENTRADAS DE RASTREIO
//
// AQUI PASSA A SER A FONTE DO "A CAMINHO"
// =========================================================

async function carregarPreEntradasRastreioEstoque() {

    if (
        !window.supabaseClient
    ) {
        return;
    }


    try {

        const {
            data: cards,
            error: erroCards
        } =
            await window.supabaseClient
                .from(
                    'entradas_cards'
                )
                .select(
                    'id, numero_entrada, status, tipo_entrada, fornecedor, dados_brutos, criado_em'
                )
                .eq(
                    'tipo_entrada',
                    'rastreio'
                )
                .order(
                    'criado_em',
                    {
                        ascending:
                            false
                    }
                );


        if (
            erroCards
        ) {
            throw erroCards;
        }


        rastreiosCompraPorProduto =
            new Map();


        produtosComHistoricoRastreioCompra =
            new Set();


        if (
            !cards ||
            cards.length === 0
        ) {

            aplicarIndicadoresACaminhoTabela();

            return;
        }


        const idsCards =
            cards.map(
                card =>
                    card.id
            );


        const {
            data: itens,
            error: erroItens
        } =
            await window.supabaseClient
                .from(
                    'entrada_items'
                )
                .select(
                    'id, entrada_id, produto_id, sku_original, sku_match, quantidade, status, rastreio, fornecedor_nome, observacao, valor_custo'
                )
                .in(
                    'entrada_id',
                    idsCards
                );


        if (
            erroItens
        ) {
            throw erroItens;
        }


        const cardsMap =
            new Map(
                cards.map(
                    card => [
                        String(
                            card.id
                        ),
                        card
                    ]
                )
            );


        for (
            const item
            of itens || []
        ) {

            let produtoId =
                item.produto_id;


            // Fallback por SKU
            if (
                !produtoId
            ) {

                const skuBusca =
                    item.sku_match ||
                    item.sku_original ||
                    '';


                const produto =
                    produtosEstoque.find(
                        p =>
                            String(
                                p.sku ||
                                ''
                            ).trim()
                            ===
                            String(
                                skuBusca
                            ).trim()
                    );


                produtoId =
                    produto?.id;

            }


            if (
                !produtoId
            ) {
                continue;
            }


            const idProduto =
                String(
                    produtoId
                );


            // Já teve rastreio alguma vez.
            produtosComHistoricoRastreioCompra
                .add(
                    idProduto
                );


            const card =
                cardsMap.get(
                    String(
                        item.entrada_id
                    )
                );


            if (!card) {
                continue;
            }


            // Só "a caminho" enquanto CARD e ITEM
            // estiverem pendentes.
            if (
                card.status !==
                    'pendente'
                ||
                item.status !==
                    'pendente'
            ) {

                continue;

            }


            const metadata =
                obterMetadadosRastreioCard(
                    card
                );


            const detalhe = {

                entrada_id:
                    card.id,

                numero_entrada:
                    card.numero_entrada,

                rastreio:
                    item.rastreio ||
                    metadata.rastreio ||
                    '',

                fornecedor:
                    item.fornecedor_nome ||
                    card.fornecedor ||
                    metadata.fornecedor ||
                    '',

                quantidade:
                    Number(
                        item.quantidade
                    ) || 0,

                custo_unitario:
                    Number(
                        item.valor_custo
                    ) || 0,

                valor_total_compra:
                    Number(
                        metadata
                            .valor_total_compra
                    ) || 0,

                dias_para_chegar:
                    Number(
                        metadata
                            .dias_para_chegar
                    ) || 0,

                previsao_chegada:
                    metadata
                        .previsao_chegada ||
                    '',

                observacao:
                    metadata
                        .observacao ||
                    '',

                criado_em:
                    card.criado_em

            };


            if (
                !rastreiosCompraPorProduto
                    .has(
                        idProduto
                    )
            ) {

                rastreiosCompraPorProduto
                    .set(
                        idProduto,
                        []
                    );

            }


            rastreiosCompraPorProduto
                .get(
                    idProduto
                )
                .push(
                    detalhe
                );

        }


        console.log(
            `🚚 Rastreios carregados para ${rastreiosCompraPorProduto.size} produto(s).`
        );


        aplicarIndicadoresACaminhoTabela();


    } catch (error) {

        console.error(
            '❌ Erro carregando pré-entradas de rastreio:',
            error
        );

    }
}


// =========================================================
// DETALHES PENDENTES DE UM PRODUTO
// =========================================================

function obterRastreiosPendentesProduto(
    produto
) {

    if (!produto) {
        return [];
    }


    return (
        rastreiosCompraPorProduto.get(
            String(
                produto.id
            )
        ) ||
        []
    );
}


// =========================================================
// PRÓXIMA PREVISÃO
// =========================================================

function obterProximaPrevisaoProduto(
    produto
) {

    const rastreios =
        obterRastreiosPendentesProduto(
            produto
        )
        .filter(
            item =>
                item.previsao_chegada
        )
        .sort(
            (a, b) =>
                String(
                    a.previsao_chegada
                ).localeCompare(
                    String(
                        b.previsao_chegada
                    )
                )
        );


    return (
        rastreios[0]
            ?.previsao_chegada ||
        ''
    );
}

