async function inicializarRegrasCategoriasCustomizadas() {

    console.log(
        '🔄 Verificando regras das categorias customizadas...'
    );


    // Impede que regras padrão sejam criadas antes
    // do carregamento das regras salvas.
    if (
        window.regrasEstoqueCarregadasGestao !==
        true
    ) {

        console.log(
            '⏳ As regras salvas ainda não foram carregadas.'
        );


        return {

            success:
                true,

            aguardando:
                true,

            alterado:
                false

        };
    }


    if (
        !categoriasCustomizadas ||
        typeof categoriasCustomizadas !==
            'object'
    ) {

        return {

            success:
                true,

            alterado:
                false

        };
    }


    let alterado =
        false;


    const categoriasCustom =
        Object.keys(
            categoriasCustomizadas
        );


    for (
        const categoria
        of categoriasCustom
    ) {

        if (
            !categoria
        ) {

            continue;

        }


        if (
            !regrasEstoqueAtuais[
                categoria
            ]
        ) {

            regrasEstoqueAtuais[
                categoria
            ] = {

                condicoes: [

                    {

                        operador:
                            'padrao',

                        estoque_maximo:
                            30

                    }

                ]

            };


            alterado =
                true;


            console.log(
                `✅ Regra criada para a nova categoria: ${categoria}`
            );


            continue;
        }


        if (
            !Array.isArray(
                regrasEstoqueAtuais[
                    categoria
                ].condicoes
            )
        ) {

            regrasEstoqueAtuais[
                categoria
            ].condicoes = [];

        }


        const temPadrao =
            regrasEstoqueAtuais[
                categoria
            ].condicoes.some(
                condicao =>
                    condicao.operador ===
                    'padrao'
            );


        if (
            !temPadrao
        ) {

            regrasEstoqueAtuais[
                categoria
            ].condicoes.push(
                {

                    operador:
                        'padrao',

                    estoque_maximo:
                        30

                }
            );


            alterado =
                true;


            console.log(
                `✅ Condição padrão acrescentada à categoria: ${categoria}`
            );

        }

    }


    if (
        alterado
    ) {

        const resultado =
            await salvarRegrasEstoque(
                regrasEstoqueAtuais,
                true
            );


        if (
            !resultado.success
        ) {

            console.error(
                '❌ Erro salvando regras das novas categorias:',
                resultado.error
            );


            return resultado;

        }

    }


    return {

        success:
            true,

        alterado

    };
}

